window.TADABBUR_WAQIA = {"_meta":{"description":"تدبّر سورة الواقعة (٥٦) — سورةٌ مكّيّةٌ. محورُها تقريرُ القيامةِ (الواقعة) وانقسامِ الناسِ يومئذٍ ثلاثةَ أصناف: السابقون المقرّبون، وأصحابُ اليمين، وأصحابُ الشمال، ووصفُ نعيمِ الأوّلين وعذابِ الآخرين، وإقامةُ الأدلّةِ على البعثِ بالنطفةِ والزرعِ والماءِ والنار، وتعظيمُ القرآن، ومشهدُ الاحتضار. فيها «والسابقون السابقون أولئك المقربون»، و«نحن خلقناكم فلولا تصدقون»، و«إنه لقرآن كريم في كتاب مكنون»، و«فلولا إذا بلغت الحلقوم».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":56,"name":"الواقعة","total_ayahs":96,"audio":[1,10,20,35,48,57,63,74,83,96],"passages":[{"title":"وقوعُ الواقعةِ وانقسامُ الناسِ ثلاثةَ أصناف","range":[1,14],"theme":"تقريرُ وقوعِ القيامةِ الخافضةِ الرافعةِ إذ تُرَجُّ الأرضُ وتُبَسُّ الجبال، وانقسامُ الناسِ أزواجًا ثلاثة: أصحابُ الميمنة، وأصحابُ المشأمة، والسابقون المقرّبون في جنّاتِ النعيمِ ثلّةٌ من الأولين وقليلٌ من الآخرين","verses":[{"n":1,"reflection":{"text":"«إذا وقعت الواقعة» — إذا قامت القيامةُ الواقعةُ التي لا بدّ منها؛ ففي هذا تقريرُ وقوعِ القيامة؛ فأيقن بوقوعِ القيامةِ واستعدّ لها، فالقيامةُ واقعةٌ حتمًا، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بوقوعِ القيامةِ والاستعدادُ لها."},"action":{"text":"تأمّل تقريرَ وقوعِ القيامة: إذا وقعت الواقعةُ — وهي القيامةُ التي تقع وتحدث لا محالة، سُمّيت واقعةً لتحقّقِ وقوعها «إذا وقعت الواقعة»؛ ففي هذا تقريرُ وقوعِ القيامةِ حتمًا؛ فهي واقعةٌ لا شكَّ فيها؛ فأيقن أنت بوقوعِ القيامةِ يقينًا جازمًا؛ إنّ الساعةَ آتيةٌ لا ريبَ فيها؛ الحاقّة ما الحاقّة؛ القارعة ما القارعة؛ فاستعدّ للقيامةِ بالإيمانِ والعملِ الصالح؛ فمن أيقن بوقوعها واستعدّ نجا، ومن أنكرها أو غفل خسر؛ فاجعل اليقينَ بوقوعِ القيامةِ والاستعدادَ لها دأبك."}},{"n":2,"reflection":{"text":"«ليس لوقعتها كاذبة» — ليس لوقوعِها نفسٌ تكذّب به، فهو حقٌّ لا مردَّ له؛ ففي هذا تأكيدُ صدقِ وقوعِ القيامة؛ فأيقن بصدقِ وقوعِ القيامةِ ولا تكذّب به، فوقوعُها حقٌّ، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بصدقِ وقوعِ القيامة، وتركُ التكذيبِ به."},"action":{"text":"تأمّل تأكيدَ صدقِ الوقوع: ليس لوقعتِها كاذبةٌ — أي ليس لوقوعِ القيامةِ نفسٌ تكذّب بوقوعها بعد أن تقع، أو ليس في الإخبارِ عنها كذب، فهي حقٌّ واقعٌ لا مردَّ له «ليس لوقعتها كاذبة»؛ ففي هذا تأكيدُ صدقِ وقوعِ القيامةِ وحتميّته؛ فلا يكذّب بها أحدٌ حين تقع؛ فأيقن أنت بصدقِ وقوعِ القيامةِ ولا تكذّب به؛ فوقوعُها حقٌّ ثابتٌ لا شكَّ فيه؛ وأنّ الساعةَ آتيةٌ لا ريبَ فيها؛ فاعمل لها بالإيمانِ والعملِ الصالح؛ فمن أيقن بصدقِ وقوعها عمل لها، ومن كذّب بها خسر؛ فاجعل اليقينَ بصدقِ وقوعِ القيامةِ وتركَ التكذيبِ به دأبك."}},{"n":3,"reflection":{"text":"«خافضة رافعة» — القيامةُ خافضةٌ لأقوامٍ (إلى النار)، رافعةٌ لأقوام (إلى الجنّة)؛ ففي هذا بيانُ أنّ القيامةَ تميّز الناس؛ فاعمل لتكون ممّن ترفعهم القيامةُ لا ممّن تخفضهم، فالقيامةُ ترفع أهلَ الطاعةِ وتخفض أهلَ المعصية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنيلِ الرفعةِ يومَ القيامة، والحذرُ من الخفض."},"action":{"text":"تأمّل أنّ القيامةَ تميّز الناس: القيامةُ خافضةٌ — أي تخفض أقوامًا فتضعهم في الدركاتِ السفلى في النار (أهلَ المعصيةِ والكفر)؛ رافعةٌ — أي ترفع أقوامًا فتعليهم في الدرجاتِ العلى في الجنّة (أهلَ الطاعةِ والإيمان)؛ فتميّز الناسَ وتفصلهم «خافضة رافعة»؛ ففي هذا بيانُ أنّ القيامةَ تخفض قومًا وترفع آخرين بحسبِ أعمالهم؛ فترفع المطيعين وتخفض العاصين؛ فاعمل أنت لتكون ممّن ترفعهم القيامةُ إلى الدرجاتِ العلى، لا ممّن تخفضهم إلى الدركاتِ السفلى؛ يرفع الله الذين آمنوا منكم والذين أوتوا العلمَ درجات؛ وجوهٌ يومئذٍ ناعمة، لسعيها راضية؛ فالقيامةُ ترفع أهلَ الطاعةِ وتخفض أهلَ المعصية؛ فمن عمل صالحًا رُفِع، ومن أساء خُفِض؛ فاجعل العملَ لنيلِ الرفعةِ والحذرَ من الخفضِ دأبك."}},{"n":4,"reflection":{"text":"«إذا رجت الأرض رجا» — إذا زُلزِلت الأرضُ واضطربت اضطرابًا شديدًا؛ ففي هذا بيانُ أهوالِ القيامة؛ فاستعدّ ليومٍ تضطرب فيه الأرض، فأهوالُ القيامةِ عظيمة، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ لأهوالِ القيامة، والعملُ لها."},"action":{"text":"تأمّل أهوالَ القيامة: إذا رُجّت الأرضُ رجًّا — أي زُلزِلت وحُرِّكت واضطربت اضطرابًا شديدًا عنيفًا عند قيامِ الساعة «إذا رجت الأرض رجا»؛ ففي هذا بيانُ بعضِ أهوالِ القيامة: رجُّ الأرضِ واضطرابها؛ فتضطرب الأرضُ الثابتةُ من هولِ ذلك اليوم؛ فاستعدّ أنت ليومٍ تضطرب فيه الأرضُ وترتجّ؛ إذا زُلزِلت الأرضُ زلزالها؛ يومَ ترجف الأرضُ والجبال؛ إذا رُجّت الأرضُ رجًّا؛ فأهوالُ القيامةِ عظيمةٌ ترتجّ لها الأرض؛ فاعمل أنت لذلك اليومِ بالإيمانِ والعملِ الصالح؛ فمن استعدّ لأهوالِ القيامةِ نجا، ومن غفل عنها خسر؛ فاجعل الاستعدادَ لأهوالِ القيامةِ والعملَ لها دأبك."}},{"n":5,"reflection":{"text":"«وبست الجبال بسا» — وفُتّتت الجبالُ تفتيتًا؛ ففي هذا تتمّةُ أهوالِ القيامة؛ فاستعدّ ليومٍ تُفتَّت فيه الجبالُ الراسيات، فإذا زالت الجبالُ فما بالك بغيرها، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ زوالِ الجبال، والعملُ له."},"action":{"text":"تأمّل تتمّةَ الأهوال: وبُسّت الجبالُ بسًّا — أي فُتّتت وكُسِّرت وصارت رملًا سائلًا، أو سِيقت وسُيّرت «وبست الجبال بسا»؛ ففي هذا بيانُ هولٍ آخرَ من أهوالِ القيامة: بسُّ الجبالِ وتفتيتها؛ فالجبالُ الراسياتُ الثوابتُ تُفتَّت وتزول من هولِ ذلك اليوم؛ فاستعدّ أنت ليومٍ تُفتَّت فيه الجبال؛ وتكون الجبالُ كالعهنِ المنفوش؛ وبُسّت الجبالُ بسًّا؛ وسُيِّرت الجبالُ فكانت سرابًا؛ فإذا زالت الجبالُ الثوابتُ فما بالك بغيرها من الأهوال؟ فاعمل أنت لذلك اليومِ العظيمِ بالإيمانِ والعملِ الصالح؛ فمن استعدّ له نجا، ومن غفل عنه خسر؛ فاجعل الاستعدادَ ليومِ زوالِ الجبالِ والعملَ له دأبك."}},{"n":6,"reflection":{"text":"«فكانت هباء منبثا» — فصارت الجبالُ غبارًا منتشرًا؛ ففي هذا بيانُ تمامِ زوالِ الجبال؛ فاعتبر بزوالِ أعظمِ المخلوقاتِ الثابتة، فكلُّ شيءٍ زائلٌ إلا الله، فاعمل للباقي.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بزوالِ المخلوقات، والعملُ للباقي."},"action":{"text":"تأمّل تمامَ زوالِ الجبال: فكانت الجبالُ بعد تفتيتها هباءً منبثًّا — أي غبارًا دقيقًا متفرّقًا منتشرًا في الهواء، كالذي يُرى في شعاعِ الشمسِ من الدقائق «فكانت هباء منبثا»؛ ففي هذا بيانُ تمامِ زوالِ الجبالِ وصيرورتها غبارًا منتشرًا؛ فتزول الجبالُ الراسياتُ حتى تصير هباءً؛ فاعتبر أنت بزوالِ أعظمِ المخلوقاتِ الثابتةِ (الجبال)؛ فإذا زالت الجبالُ فكلُّ شيءٍ زائل؛ كلُّ من عليها فان؛ كلُّ شيءٍ هالكٌ إلا وجهه؛ وترى الجبالَ تحسبها جامدةً وهي تمرُّ مرَّ السحاب؛ فكلُّ شيءٍ زائلٌ إلا الله؛ فاعمل أنت للباقي — وهو الله والدارُ الآخرة — لا للفاني الزائل؛ فمن اعتبر بزوالِ المخلوقاتِ وعمل للباقي نجا، ومن ركن إلى الفاني خسر؛ فاجعل الاعتبارَ بزوالِ المخلوقاتِ والعملَ للباقي دأبك."}},{"n":7,"reflection":{"text":"«وكنتم أزواجا ثلاثة» — وصرتم يومَ القيامةِ أصنافًا ثلاثة؛ ففي هذا بيانُ انقسامِ الناسِ ثلاثةَ أصناف؛ فاعمل لتكون من أفضلِ الأصناف (السابقين أو أصحابِ اليمين)، فالناسُ يومَ القيامةِ أصنافٌ بحسبِ أعمالهم، فاختر لنفسك أعلاها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكونَ من أفضلِ الأصناف، وإدراكُ انقسامِ الناس."},"action":{"text":"تأمّل انقسامَ الناسِ ثلاثةَ أصناف: وكنتم — أيها الناس — يومَ القيامةِ أزواجًا ثلاثةً — أي أصنافًا وأقسامًا ثلاثة، بحسبِ أعمالكم: السابقون المقرّبون، وأصحابُ اليمين، وأصحابُ الشمال «وكنتم أزواجا ثلاثة»؛ ففي هذا بيانُ انقسامِ الناسِ يومَ القيامةِ ثلاثةَ أصناف؛ فيتميّزون بحسبِ أعمالهم؛ فاعمل أنت لتكون من أفضلِ الأصناف: السابقين المقرّبين، أو أصحابِ اليمين؛ ولا تكن من أصحابِ الشمال؛ فمنهم ظالمٌ لنفسه ومنهم مقتصدٌ ومنهم سابقٌ بالخيرات؛ فأصحابُ الميمنةِ وأصحابُ المشأمةِ والسابقون؛ فالناسُ يومَ القيامةِ أصنافٌ بحسبِ أعمالهم؛ فاختر لنفسك أعلى الأصنافِ بالعملِ الصالح؛ فمن عمل صالحًا كان من أهلِ اليمينِ أو السابقين، ومن أساء كان من أهلِ الشمال؛ فاجعل العملَ لتكونَ من أفضلِ الأصنافِ دأبك."}},{"n":8,"reflection":{"text":"«فأصحاب الميمنة ما أصحاب الميمنة» — فأصحابُ اليمين (أهلُ السعادة) ما أعظمَ شأنهم؛ ففي هذا تعظيمُ شأنِ أصحابِ اليمين؛ فاعمل لتكون من أصحابِ اليمينِ السعداء، فأصحابُ اليمينِ لهم شأنٌ عظيم، فاجتهد لتكون منهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكونَ من أصحابِ اليمينِ السعداء."},"action":{"text":"تأمّل تعظيمَ شأنِ أصحابِ اليمين: فأصحابُ الميمنةِ — أي أصحابُ اليمينِ الذين يأخذون كتبهم بأيمانهم، أو الميامينُ على أنفسهم، وهم أهلُ السعادةِ والجنّة — ما أصحابُ الميمنة؟ استفهامُ تعظيمٍ لشأنهم وحالهم «فأصحاب الميمنة ما أصحاب الميمنة»؛ ففي هذا تعظيمُ شأنِ أصحابِ اليمينِ وحالهم؛ فلهم شأنٌ عظيمٌ من النعيمِ والكرامة؛ فاعمل أنت لتكون من أصحابِ اليمينِ السعداء؛ فأصحابُ اليمينِ ما أصحابُ اليمين، في سدرٍ مخضود؛ وأمّا إن كان من أصحابِ اليمينِ فسلامٌ لك من أصحابِ اليمين؛ فأصحابُ اليمينِ لهم شأنٌ عظيمٌ من النعيم؛ فاجتهد بالإيمانِ والعملِ الصالحِ لتكون منهم؛ فمن عمل صالحًا كان منهم، ومن أساء حُرِم؛ فاجعل العملَ لتكونَ من أصحابِ اليمينِ السعداءِ دأبك."}},{"n":9,"reflection":{"text":"«وأصحاب المشأمة ما أصحاب المشأمة» — وأصحابُ الشمال (أهلُ الشقاء) ما أسوأَ حالهم؛ ففي هذا تهويلُ شأنِ أصحابِ الشمال؛ فاحذر أن تكون من أصحابِ الشمالِ الأشقياء، فأصحابُ الشمالِ لهم شأنٌ سيّئ، فاجتنب أعمالهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ أعمالِ أصحابِ الشمال، والحذرُ من الشقاء."},"action":{"text":"تأمّل تهويلَ شأنِ أصحابِ الشمال: وأصحابُ المشأمةِ — أي أصحابُ الشمالِ الذين يأخذون كتبهم بشمائلهم، أو المشائيمُ على أنفسهم، وهم أهلُ الشقاءِ والنار — ما أصحابُ المشأمة؟ استفهامُ تهويلٍ وتفظيعٍ لسوءِ حالهم «وأصحاب المشأمة ما أصحاب المشأمة»؛ ففي هذا تهويلُ شأنِ أصحابِ الشمالِ وسوءِ حالهم؛ فلهم شأنٌ سيّئٌ من العذابِ والهوان؛ فاحذر أنت أن تكون من أصحابِ الشمالِ الأشقياء؛ وأصحابُ الشمالِ ما أصحابُ الشمال، في سمومٍ وحميم؛ وأمّا إن كان من المكذّبين الضالّين فنزلٌ من حميم؛ فأصحابُ الشمالِ لهم شأنٌ سيّئٌ من العذاب؛ فاجتنب أعمالهم من الكفرِ والإصرارِ على المعاصي؛ فمن اجتنب أعمالهم نجا، ومن عملها هلك؛ فاجعل اجتنابَ أعمالِ أصحابِ الشمالِ والحذرَ من الشقاءِ دأبك."}},{"n":10,"reflection":{"text":"«والسابقون السابقون» — والسابقون إلى الخيراتِ في الدنيا هم السابقون إلى الجنّةِ في الآخرة؛ ففي هذا بيانُ فضلِ السابقين؛ فسابق إلى الخيراتِ لتكون من السابقين، فالسبقُ إلى الخيرِ سبيلُ السبقِ إلى الجنّة، فبادر إلى الطاعات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المسابقةُ إلى الخيرات، لتكونَ من السابقين إلى الجنّة."},"action":{"text":"تأمّل فضلَ السابقين: والسابقون إلى الخيراتِ والطاعاتِ والإيمانِ في الدنيا، هم السابقون إلى الجنّةِ والدرجاتِ العلى في الآخرة؛ فمن سبق هنا سبق هناك «والسابقون السابقون»؛ ففي هذا بيانُ فضلِ السابقين إلى الخيرات، وأنهم السابقون إلى الجنّة؛ فسبقهم في الدنيا يورث سبقهم في الآخرة؛ فسابق أنت إلى الخيراتِ والطاعاتِ لتكون من السابقين؛ وسارعوا إلى مغفرةٍ من ربّكم؛ سابقوا إلى مغفرةٍ من ربّكم وجنّة؛ فاستبقوا الخيرات؛ فمنهم سابقٌ بالخيراتِ بإذنِ الله ذلك هو الفضلُ الكبير؛ فالسبقُ إلى الخيرِ سبيلُ السبقِ إلى الجنّةِ والدرجاتِ العلى؛ فبادر أنت إلى الطاعاتِ ولا تتأخّر؛ فمن سابق إلى الخيراتِ كان من السابقين، ومن تأخّر فاته الفضل؛ فاجعل المسابقةَ إلى الخيراتِ دأبك."}},{"n":11,"reflection":{"text":"«أولئك المقربون» — أولئك السابقون هم المقرّبون عند الله؛ ففي هذا بيانُ منزلةِ السابقين (القرب)؛ فاطلب القربَ من الله بالسبقِ إلى الخيرات، فالقربُ من الله أعظمُ المنازل، فاجتهد لتناله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ القربِ من الله بالسبقِ إلى الخيرات."},"action":{"text":"تأمّل منزلةَ السابقين: أولئك السابقون إلى الخيراتِ هم المقرّبون عند الله، في أعلى المنازلِ والدرجات، مقرّبون من ربّهم ومن رحمته وكرامته «أولئك المقربون»؛ ففي هذا بيانُ أنّ السابقين هم المقرّبون عند الله، في أرفعِ المنازل؛ فبسبقهم نالوا القرب؛ فاطلب أنت القربَ من الله بالسبقِ إلى الخيراتِ والطاعات؛ فالقربُ من الله وكرامتُه أعظمُ المنازلِ وأشرفها؛ في مقعدِ صدقٍ عند مليكٍ مقتدر؛ وجوهٌ يومئذٍ ناضرة، إلى ربّها ناظرة؛ عينًا يشرب بها المقرّبون؛ فالقربُ من الله أعظمُ نعيمِ الجنّة؛ فاجتهد بالسبقِ إلى الخيراتِ لتنال القرب؛ فمن سبق إلى الخيراتِ نال القرب، ومن تأخّر فاته؛ فاجعل طلبَ القربِ من الله بالسبقِ إلى الخيراتِ دأبك."}},{"n":12,"reflection":{"text":"«في جنات النعيم» — المقرّبون في جنّاتِ النعيمِ الدائم؛ ففي هذا بيانُ جزاءِ المقرّبين؛ فاطلب جنّاتِ النعيمِ بالسبقِ والإحسان، فالجنّةُ جزاءُ المقرّبين، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لجنّاتِ النعيمِ بالسبقِ والإحسان."},"action":{"text":"تأمّل جزاءَ المقرّبين: المقرّبون في جنّاتِ النعيمِ — أي البساتينِ ذاتِ النعيمِ الدائمِ الكامل، الذي لا ينقطع ولا يكدّره شيء «في جنات النعيم»؛ ففي هذا بيانُ جزاءِ المقرّبين: جنّاتُ النعيمِ الدائم؛ فجزاؤهم بسبقهم وإحسانهم جنّاتُ النعيم؛ فاطلب أنت جنّاتِ النعيمِ بالسبقِ إلى الخيراتِ والإحسانِ في العمل؛ إنّ الأبرارَ لفي نعيم؛ فأمّا إن كان من المقرّبين فروحٌ وريحانٌ وجنّةُ نعيم؛ إنّ المتّقين في جنّاتٍ ونعيم؛ فالجنّةُ ونعيمها جزاءُ المقرّبين والسابقين؛ فاعمل للجنّةِ بالسبقِ والإحسانِ والإخلاص؛ فمن سبق وأحسن نال جنّاتِ النعيم، ومن تأخّر أو أساء حُرِمها؛ فاجعل العملَ لجنّاتِ النعيمِ بالسبقِ والإحسانِ دأبك."}},{"n":13,"reflection":{"text":"«ثلة من الأولين» — جماعةٌ كثيرةٌ من الأمم الأولى (السابقين)؛ ففي هذا بيانُ كثرةِ السابقين من الأولين؛ فاعلم أنّ السابقين كثيرون من الأمم الأولى، فاقتدِ بهم في السبقِ إلى الخيرات، فالسابقون قدوةٌ يُقتَدى بهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاقتداءُ بالسابقين من الأولين في السبقِ إلى الخيرات."},"action":{"text":"تأمّل كثرةَ السابقين من الأولين: السابقون المقرّبون ثلّةٌ — أي جماعةٌ كثيرةٌ — من الأمم الأولين (من لدن آدمَ إلى أمّةِ محمدٍ، أو من صدرِ هذه الأمّة)؛ فكانوا كثيرين في الأمم الأولى «ثلة من الأولين»؛ ففي هذا بيانُ أنّ السابقين المقرّبين كثيرون من الأمم الأولى؛ فكان فيهم كثرةٌ من السابقين؛ فاعلم أنت أنّ السابقين إلى الخيراتِ كثيرون في الأمم الأولى؛ فاقتدِ بهم في السبقِ إلى الخيراتِ والطاعات؛ ولقد ضللنا كثيرًا؛ فاتّبع سبيلَ السابقين المقرّبين؛ والسابقون الأوّلون من المهاجرين والأنصار والذين اتّبعوهم بإحسانٍ رضي الله عنهم؛ فالسابقون قدوةٌ يُقتَدى بهم في الخير؛ فمن اقتدى بهم كان منهم، ومن تأخّر عنهم فاته الفضل؛ فاجعل الاقتداءَ بالسابقين في السبقِ إلى الخيراتِ دأبك."}},{"n":14,"reflection":{"text":"«وقليل من الآخرين» — وعددٌ قليلٌ من الأمم الآخرة (السابقون)؛ ففي هذا بيانُ قلّةِ السابقين في الآخرين؛ فاحرص أن تكون من القليلِ السابقين ولو قلّوا، فالسبقُ إلى الخيرِ شرفٌ ولو كان أهله قليلًا، فلا يهمّنك قلّتهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على السبقِ ولو قلَّ أهله، وعدمُ الاغترارِ بالكثرة."},"action":{"text":"تأمّل قلّةَ السابقين في الآخرين: والسابقون قليلٌ من الأمم الآخرين (من أواخرِ الأمم، أو من آخرِ هذه الأمّة)؛ فقلّ السابقون في الآخرين مقارنةً بالأولين «وقليل من الآخرين»؛ ففي هذا بيانُ قلّةِ السابقين في الأمم الآخرة؛ فقلّ فيهم السابقون؛ فاحرص أنت أن تكون من القليلِ السابقين إلى الخيرات، ولو كانوا قليلين؛ فالعبرةُ بالسبقِ إلى الخيرِ لا بالكثرة؛ وقليلٌ من عبادي الشكور؛ وما آمن معه إلا قليل؛ فالسبقُ إلى الخيرِ شرفٌ ولو كان أهله قليلًا؛ فلا يهمّنك قلّةُ السابقين، بل احرص أن تكون منهم؛ فمن حرص على السبقِ كان من القليلِ الفائزين، ومن تأخّر مع الكثرةِ فاته الفضل؛ فاجعل الحرصَ على السبقِ ولو قلَّ أهله وعدمَ الاغترارِ بالكثرةِ دأبك."}}]},{"title":"نعيمُ السابقين المقرّبين","range":[15,26],"theme":"نعيمُ المقرّبين على سررٍ موضونةٍ متقابلين، يطوف عليهم ولدانٌ مخلّدون بأكوابٍ وكأسٍ من معينٍ لا يُصدَّعون عنها، وفاكهةٍ ولحمِ طيرٍ وحورٍ عينٍ كأمثالِ اللؤلؤِ جزاءً بأعمالهم، لا يسمعون فيها لغوًا ولا تأثيمًا إلا سلامًا سلامًا","verses":[{"n":15,"reflection":{"text":"«على سرر موضونة» — على أسرّةٍ منسوجةٍ بالذهبِ والجواهر؛ ففي هذا بيانُ نعيمِ المقرّبين؛ فاطلب هذا النعيمَ بالسبقِ والإحسان، فنعيمُ الجنّةِ فاخرٌ عظيم، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ بالسبقِ والإحسان."},"action":{"text":"تأمّل نعيمَ المقرّبين: المقرّبون في الجنّةِ على سررٍ موضونةٍ — أي أسرّةٍ منسوجةٍ مشبّكةٍ بالذهبِ والجواهرِ واللؤلؤ، فاخرةٍ بديعة «على سرر موضونة»؛ ففي هذا بيانُ نعيمِ المقرّبين على الأسرّةِ الفاخرة؛ فهم على سررٍ منسوجةٍ بالذهب؛ فاطلب أنت هذا النعيمَ بالسبقِ إلى الخيراتِ والإحسان؛ متّكئين على سررٍ مصفوفة؛ على الأرائكِ ينظرون؛ فنعيمُ الجنّةِ فاخرٌ عظيمٌ بديع؛ فاعمل للجنّةِ ونعيمها بالسبقِ والإحسانِ والإخلاص؛ فمن سبق وأحسن نال هذا النعيم، ومن تأخّر أو أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ بالسبقِ والإحسانِ دأبك."}},{"n":16,"reflection":{"text":"«متكئين عليها متقابلين» — متّكئين على السررِ متقابلين بوجوههم أنسًا ومحبّة؛ ففي هذا بيانُ أنسِ أهلِ الجنّة؛ فاطلب أنسَ الجنّةِ ومحبّتها بالعملِ الصالح، فأهلُ الجنّةِ في أنسٍ ومحبّة، فاعمل لها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لأنسِ الجنّةِ ومحبّتها، وطلبُ صحبةِ الصالحين."},"action":{"text":"تأمّل أنسَ أهلِ الجنّة: المقرّبون متّكئين على تلك السررِ اتّكاءَ الراحةِ والطمأنينة، متقابلين بوجوههم لا ينظر بعضهم إلى قفا بعض، في أنسٍ ومحبّةٍ وسرور «متكئين عليها متقابلين»؛ ففي هذا بيانُ أنسِ أهلِ الجنّةِ ومحبّتهم بتقابلهم؛ فهم في راحةٍ وأنسٍ ومحبّة؛ فاطلب أنت أنسَ الجنّةِ ومحبّتها وصحبتها الطيّبةَ بالعملِ الصالح؛ إخوانًا على سررٍ متقابلين؛ ونزعنا ما في صدورهم من غلٍّ إخوانًا على سررٍ متقابلين؛ فأهلُ الجنّةِ في أنسٍ ومحبّةٍ وأخوّة؛ واطلب في الدنيا صحبةَ الصالحين لتكون معهم في الآخرة؛ المرءُ مع من أحبّ؛ فاعمل للجنّةِ وأنسها بالعملِ الصالحِ وصحبةِ الأخيار؛ فمن عمل صالحًا وصاحب الأخيارَ كان معهم، ومن أساء حُرِم؛ فاجعل العملَ لأنسِ الجنّةِ ومحبّتها وطلبَ صحبةِ الصالحين دأبك."}},{"n":17,"reflection":{"text":"«يطوف عليهم ولدان مخلدون» — يطوف على المقرّبين للخدمةِ غلمانٌ باقون على شبابهم لا يهرمون؛ ففي هذا بيانُ تمامِ خدمةِ أهلِ الجنّة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فأهلُ الجنّةِ يُخدَمون أتمَّ خدمة، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ وخدمتها الكاملة."},"action":{"text":"تأمّل خدمةَ أهلِ الجنّة: يطوف على المقرّبين للخدمةِ ولدانٌ — أي غلمانٌ — مخلّدون: مبقَّون على صورةِ الشبابِ والطراوةِ أبدًا، لا يهرمون ولا يتغيّرون ولا يموتون «يطوف عليهم ولدان مخلدون»؛ ففي هذا بيانُ تمامِ خدمةِ أهلِ الجنّة، حيث يطوف عليهم غلمانٌ مخلّدون على شبابهم؛ فيُخدَمون أتمَّ خدمة؛ فاطلب أنت هذا النعيمَ بالعملِ الصالحِ والسبقِ إلى الخيرات؛ ويطوف عليهم وِلدانٌ مخلّدون إذا رأيتهم حسبتهم لؤلؤًا منثورًا؛ ويطوف عليهم غلمانٌ لهم كأنهم لؤلؤٌ مكنون؛ فأهلُ الجنّةِ يُخدَمون ويُكرَمون أتمَّ إكرام؛ فاعمل للجنّةِ ونعيمها وخدمتها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ وخدمتها الكاملةِ دأبك."}},{"n":18,"reflection":{"text":"«بأكواب وأباريق وكأس من معين» — بأكوابٍ وأباريقَ وكأسٍ من خمرٍ جاريةٍ من عين؛ ففي هذا بيانُ نعيمِ شرابِ الجنّة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فشرابُ الجنّةِ لذيذٌ دائم، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الشرابِ اللذيذ."},"action":{"text":"تأمّل نعيمَ شرابِ الجنّة: يطوف عليهم الولدانُ بأكوابٍ (أوانٍ للشربِ بلا عرًى) وأباريقَ (ذاتِ عرًى وخراطيمَ) وكأسٍ من معينٍ — أي خمرٍ جاريةٍ من عينٍ ظاهرةٍ دائمة، لذيذةٍ صافية «بأكواب وأباريق وكأس من معين»؛ ففي هذا بيانُ نعيمِ شرابِ أهلِ الجنّةِ في الآنيةِ الفاخرة؛ فيُطاف عليهم بالشرابِ اللذيذِ في الأكوابِ والأباريق؛ فاطلب أنت هذا النعيمَ بالعملِ الصالحِ والسبق؛ ويُطاف عليهم بآنيةٍ من فضّةٍ وأكوابٍ كانت قواريرا؛ يُسقَون من رحيقٍ مختوم؛ عينًا يشرب بها المقرّبون؛ فشرابُ الجنّةِ لذيذٌ دائمٌ في آنيةٍ فاخرة؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الشرابِ اللذيذِ دأبك."}},{"n":19,"reflection":{"text":"«لا يصدعون عنها ولا ينزفون» — لا يُصيبهم صداعٌ من خمرِ الجنّةِ ولا يذهب عقلهم؛ ففي هذا بيانُ طهارةِ خمرِ الجنّةِ من آفاتِ خمرِ الدنيا؛ فاطلب هذا النعيمَ الطاهرَ بالعملِ الصالح، فخمرُ الجنّةِ لذّةٌ بلا أذًى، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الطاهرِ من كلِّ أذًى."},"action":{"text":"تأمّل طهارةَ خمرِ الجنّة: أهلُ الجنّةِ لا يُصدَّعون عنها — أي لا يُصيبهم صداعٌ ولا وجعُ رأسٍ من شربِ خمرِ الجنّة؛ ولا يُنزِفون — أي لا يذهب عقلهم ولا يسكرون، بخلافِ خمرِ الدنيا «لا يصدعون عنها ولا ينزفون»؛ ففي هذا بيانُ طهارةِ خمرِ الجنّةِ من آفاتِ خمرِ الدنيا (الصداعِ والسكرِ وذهابِ العقل)؛ فهي لذّةٌ خالصةٌ بلا أذًى؛ فاطلب أنت هذا النعيمَ الطاهرَ بالعملِ الصالحِ والسبق؛ لا فيها غولٌ ولا هم عنها يُنزَفون؛ لا يُصدَّعون عنها ولا يُنزِفون؛ لا لغوَ فيها ولا تأثيم؛ بيضاءَ لذّةٍ للشاربين؛ فخمرُ الجنّةِ لذّةٌ خالصةٌ بلا صداعٍ ولا سُكرٍ ولا أذًى؛ فاعمل للجنّةِ ونعيمها الطاهرِ بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيمَ الطاهر، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الطاهرِ دأبك."}},{"n":20,"reflection":{"text":"«وفاكهة مما يتخيرون» — وفاكهةٍ ممّا يختارون ويشتهون؛ ففي هذا بيانُ سعةِ نعيمِ الجنّةِ من الفاكهة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فثمارُ الجنّةِ متنوّعةٌ يختارها أهلها، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الفاكهةِ المختارة."},"action":{"text":"تأمّل نعيمَ فاكهةِ الجنّة: يُطاف على أهلِ الجنّةِ بفاكهةٍ ممّا يتخيّرون — أي ممّا يختارون ويشتهون من أنواعِ الفاكهةِ اللذيذةِ المتنوّعة؛ فلهم أن يختاروا ما شاؤوا منها «وفاكهة مما يتخيرون»؛ ففي هذا بيانُ سعةِ نعيمِ أهلِ الجنّةِ من الفاكهة، وأنهم يتخيّرون منها ما شاؤوا؛ فاطلب أنت هذا النعيمَ بالعملِ الصالحِ والسبق؛ ولهم فيها من كلِّ الثمرات؛ وفاكهةٍ كثيرةٍ لا مقطوعةٍ ولا ممنوعة؛ فيهما من كلِّ فاكهةٍ زوجان؛ فثمارُ الجنّةِ متنوّعةٌ كثيرةٌ يختارها أهلها كيف شاؤوا؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الفاكهةِ المختارةِ دأبك."}},{"n":21,"reflection":{"text":"«ولحم طير مما يشتهون» — ولحمِ طيرٍ ممّا يشتهون؛ ففي هذا بيانُ سعةِ نعيمِ الجنّة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فنعيمُ الجنّةِ يشمل كلَّ ما تشتهي النفس، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الذي يشمل كلَّ ما تشتهي النفس."},"action":{"text":"تأمّل سعةَ نعيمِ الجنّة: ويُطاف على أهلِ الجنّةِ بلحمِ طيرٍ ممّا يشتهون — أي ممّا تشتهيه أنفسهم من أطايبِ لحومِ الطير؛ فيُعطَون ما يشتهون منه «ولحم طير مما يشتهون»؛ ففي هذا بيانُ سعةِ نعيمِ الجنّة، حيث يُعطَون لحمَ الطيرِ الذي يشتهون؛ فاطلب أنت هذا النعيمَ بالعملِ الصالحِ والسبق؛ وأمددناهم بفاكهةٍ ولحمٍ ممّا يشتهون؛ فيها ما تشتهيه الأنفسُ وتلذُّ الأعين؛ ولكم فيها ما تشتهي أنفسكم؛ فنعيمُ الجنّةِ يشمل كلَّ ما تشتهي النفسُ وتلذُّ العين؛ فاعمل للجنّةِ ونعيمها الكاملِ بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الذي يشمل كلَّ ما تشتهي النفسُ دأبك."}},{"n":22,"reflection":{"text":"«وحور عين» — ولهم حورٌ عينٌ (نساءٌ بيضٌ واسعاتُ العيونِ حسان)؛ ففي هذا بيانُ نعيمِ الجنّةِ من الأزواج؛ فاطلب هذا النعيمَ بالعملِ الصالح، فأزواجُ الجنّةِ حسانٌ طاهرات، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الأزواجِ الحسان."},"action":{"text":"تأمّل نعيمَ أزواجِ الجنّة: ولأهلِ الجنّةِ حورٌ عينٌ — أي نساءٌ بيضٌ حسانٌ واسعاتُ العيونِ جميلاتها، في غايةِ الحسنِ والجمال «وحور عين»؛ ففي هذا بيانُ نعيمِ أهلِ الجنّةِ من الأزواجِ الحورِ العين؛ فأزواجهم في غايةِ الحسن؛ فاطلب أنت هذا النعيمَ بالعملِ الصالحِ والسبق؛ وزوّجناهم بحورٍ عين؛ فيهنّ قاصراتُ الطرف؛ كأنهنّ الياقوتُ والمرجان؛ فأزواجُ الجنّةِ حسانٌ طاهراتٌ عفيفات؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الأزواجِ الحسانِ دأبك."}},{"n":23,"reflection":{"text":"«كأمثال اللؤلؤ المكنون» — كأنّ الحورَ في صفائهنّ اللؤلؤُ المصونُ في صدفه؛ ففي هذا بيانُ حسنِ أزواجِ الجنّةِ وصفائهنّ؛ فاطلب هذا النعيمَ بالعملِ الصالح، فأزواجُ الجنّةِ في غايةِ الصفاءِ والحسن، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الأزواجِ الصافياتِ الحسان."},"action":{"text":"تأمّل صفاءَ أزواجِ الجنّة: الحورُ العينُ كأمثالِ اللؤلؤِ المكنونِ — أي المصونِ في صدفه الذي لم تمسّه الأيدي ولم تغيّره الشمس، في صفائه وبياضه ونقائه؛ فهنّ في غايةِ الصفاءِ والحسن «كأمثال اللؤلؤ المكنون»؛ ففي هذا بيانُ حسنِ أزواجِ الجنّةِ وصفائهنّ ونقائهنّ، بتشبيههنّ باللؤلؤِ المكنون؛ فاطلب أنت هذا النعيمَ بالعملِ الصالحِ والسبق؛ كأنهنّ بيضٌ مكنون؛ كأنهنّ الياقوتُ والمرجان؛ حورٌ مقصوراتٌ في الخيام؛ فأزواجُ الجنّةِ في غايةِ الصفاءِ والحسنِ والنقاء؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الأزواجِ الصافياتِ الحسانِ دأبك."}},{"n":24,"reflection":{"text":"«جزاء بما كانوا يعملون» — كان ذلك النعيمُ جزاءً بما كانوا يعملون في الدنيا؛ ففي هذا بيانُ أنّ نعيمَ الجنّةِ ثمرةُ العمل؛ فاعمل صالحًا لتُجزى بنعيمِ الجنّة، فالنعيمُ جزاءُ العملِ الصالح، فاجعل العملَ الصالحَ دأبك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ لنيلِ نعيمِ الجنّةِ جزاءً."},"action":{"text":"تأمّل أنّ النعيمَ ثمرةُ العمل: كان ذلك النعيمُ العظيمُ للمقرّبين جزاءً وثوابًا بما كانوا يعملون في الدنيا من الإيمانِ والطاعاتِ والسبقِ إلى الخيرات «جزاء بما كانوا يعملون»؛ ففي هذا بيانُ أنّ نعيمَ الجنّةِ للمقرّبين ثمرةُ أعمالهم الصالحةِ في الدنيا؛ فبأعمالهم نالوا النعيم؛ فاعمل أنت عملًا صالحًا لتُجزى بنعيمِ الجنّة؛ كلوا واشربوا هنيئًا بما أسلفتم في الأيامِ الخالية؛ وتلك الجنّةُ التي أورثتموها بما كنتم تعملون؛ جزاءً بما كانوا يكسبون؛ فالنعيمُ جزاءُ العملِ الصالحِ والسبقِ إلى الخيرات؛ فاعمل صالحًا مخلصًا لله؛ فمن عمل صالحًا نال النعيم، ومن فرّط حُرِمه؛ فاجعل العملَ الصالحَ لنيلِ نعيمِ الجنّةِ دأبك."}},{"n":25,"reflection":{"text":"«لا يسمعون فيها لغوا ولا تأثيما» — لا يسمعون في الجنّةِ باطلًا ولا كلامًا فيه إثم؛ ففي هذا بيانُ طهارةِ مجالسِ الجنّةِ من اللغوِ والإثم؛ فاطلب هذا النعيمَ الطاهرَ بالعملِ الصالح، وطهّر مجلسك في الدنيا من اللغوِ والإثم، فطهارةُ المجلسِ من صفاتِ أهلِ الجنّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تطهيرُ المجلسِ من اللغوِ والإثم، والعملُ لنعيمِ الجنّةِ الطاهر."},"action":{"text":"تأمّل طهارةَ مجالسِ الجنّة: لا يسمع أهلُ الجنّةِ فيها لغوًا — أي باطلًا وكلامًا لا فائدةَ فيه؛ ولا تأثيمًا — أي كلامًا فيه إثمٌ كالكذبِ والغيبةِ والفحش؛ فمجالسهم طاهرةٌ من كلِّ لغوٍ وإثم «لا يسمعون فيها لغوا ولا تأثيما»؛ ففي هذا بيانُ طهارةِ مجالسِ الجنّةِ من اللغوِ والإثمِ والكلامِ السيّئ؛ فلا يسمعون إلا الطيّبَ من القول؛ فاطلب أنت هذا النعيمَ الطاهرَ بالعملِ الصالح؛ لا يسمعون فيها لغوًا إلا سلامًا؛ وإذا سمعوا اللغوَ أعرضوا عنه؛ والذين هم عن اللغوِ معرضون؛ فطهّر أنت مجلسك في الدنيا من اللغوِ والإثمِ والكلامِ السيّئ؛ فطهارةُ المجلسِ من صفاتِ أهلِ الجنّة؛ فمن طهّر مجلسه وعمل صالحًا نال نعيمَ الجنّةِ الطاهر، ومن لها بالباطلِ حُرِم؛ فاجعل تطهيرَ المجلسِ من اللغوِ والإثمِ والعملَ لنعيمِ الجنّةِ الطاهرِ دأبك."}},{"n":26,"reflection":{"text":"«إلا قيلا سلاما سلاما» — إلا قولًا هو سلامٌ بعد سلام؛ ففي هذا بيانُ أنّ كلامَ أهلِ الجنّةِ سلامٌ طيّب؛ فاجعل كلامك طيّبًا كسلامِ أهلِ الجنّة، وأفشِ السلامَ في الدنيا، فالكلامُ الطيّبُ والسلامُ من صفاتِ أهلِ الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الكلامُ الطيّبُ وإفشاءُ السلام، اقتداءً بأهلِ الجنّة."},"action":{"text":"تأمّل أنّ كلامَ أهلِ الجنّةِ سلام: لا يسمع أهلُ الجنّةِ إلا قيلًا — أي قولًا — هو سلامٌ بعد سلام: يسلّم بعضهم على بعض، وتسلّم عليهم الملائكة، ويسلّم عليهم ربّهم؛ فكلامهم كلُّه طيّبٌ سالمٌ من كلِّ عيب «إلا قيلا سلاما سلاما»؛ ففي هذا بيانُ أنّ كلامَ أهلِ الجنّةِ سلامٌ طيّبٌ لا لغوَ فيه ولا إثم؛ فتحيّتهم فيها سلام؛ فاجعل أنت كلامك طيّبًا سالمًا كسلامِ أهلِ الجنّة؛ وقولوا للناسِ حسنًا؛ من كان يؤمن بالله واليومِ الآخرِ فليقل خيرًا أو ليصمت؛ وأفشِ السلامَ في الدنيا بين الناس؛ أفشوا السلامَ بينكم؛ فالكلامُ الطيّبُ وإفشاءُ السلامِ من صفاتِ أهلِ الجنّة؛ فمن أطاب كلامه وأفشى السلامَ اقتدى بهم، ومن أساء كلامه خالفهم؛ فاجعل الكلامَ الطيّبَ وإفشاءَ السلامِ دأبك."}}]},{"title":"نعيمُ أصحابِ اليمين","range":[27,38],"theme":"نعيمُ أصحابِ اليمينِ في سدرٍ مخضودٍ وطلحٍ منضودٍ وظلٍّ ممدودٍ وماءٍ مسكوبٍ وفاكهةٍ كثيرةٍ لا مقطوعةٍ ولا ممنوعةٍ وفرشٍ مرفوعة، وأنّ أزواجهم أُنشِئن إنشاءً فجُعِلن أبكارًا عُرُبًا أترابًا لأصحابِ اليمين","verses":[{"n":27,"reflection":{"text":"«وأصحاب اليمين ما أصحاب اليمين» — وأصحابُ اليمين ما أعظمَ شأنهم؛ ففي هذا تعظيمُ شأنِ أصحابِ اليمين؛ فاعمل لتكون من أصحابِ اليمين، فلهم شأنٌ عظيمٌ من النعيم، فاجتهد لتكون منهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكونَ من أصحابِ اليمين، وطلبُ نعيمهم."},"action":{"text":"تأمّل تعظيمَ شأنِ أصحابِ اليمين: وأصحابُ اليمين — وهم الصنفُ الثاني من أهلِ الجنّةِ دون المقرّبين — ما أصحابُ اليمين؟ استفهامُ تعظيمٍ لشأنهم وحالهم ونعيمهم «وأصحاب اليمين ما أصحاب اليمين»؛ ففي هذا تعظيمُ شأنِ أصحابِ اليمينِ وحالهم؛ فلهم شأنٌ عظيمٌ من النعيمِ والكرامة؛ فاعمل أنت لتكون من أصحابِ اليمينِ السعداء؛ فأصحابُ اليمينِ في سدرٍ مخضود؛ وأمّا إن كان من أصحابِ اليمينِ فسلامٌ لك؛ فأولئك أصحابُ الميمنة؛ فأصحابُ اليمينِ لهم شأنٌ عظيمٌ من النعيم؛ فاجتهد بالإيمانِ والعملِ الصالحِ لتكون منهم؛ فمن عمل صالحًا كان منهم، ومن أساء حُرِم؛ فاجعل العملَ لتكونَ من أصحابِ اليمينِ وطلبَ نعيمهم دأبك."}},{"n":28,"reflection":{"text":"«في سدر مخضود» — في سدرٍ (نبقٍ) لا شوكَ فيه؛ ففي هذا بيانُ نعيمِ أصحابِ اليمين؛ فاطلب هذا النعيمَ بالعملِ الصالح، فنعيمُ الجنّةِ خالٍ من كلِّ أذًى، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الخالي من كلِّ أذًى."},"action":{"text":"تأمّل نعيمَ أصحابِ اليمين: أصحابُ اليمين في سدرٍ مخضودٍ — أي في شجرِ نبقٍ قد خُضِد شوكه وقُطِع، فلا شوكَ فيه، مثمرٍ وارف؛ فنعيمهم خالٍ من الأذى «في سدر مخضود»؛ ففي هذا بيانُ نعيمِ أصحابِ اليمينِ في السدرِ الذي لا شوكَ فيه؛ فشجرُ جنّتهم بلا شوكٍ ولا أذى؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ فنعيمُ الجنّةِ خالٍ من كلِّ أذًى ونقصٍ وكدر؛ لا يمسّهم فيها نصبٌ وما هم منها بمخرَجين؛ لا يسمعون فيها لغوًا؛ فاعمل للجنّةِ ونعيمها الخالي من الأذى بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الخالي من كلِّ أذًى دأبك."}},{"n":29,"reflection":{"text":"«وطلح منضود» — وشجرِ موزٍ (أو طلحٍ) متراكبِ الثمرِ منضود؛ ففي هذا بيانُ نعيمِ أصحابِ اليمين؛ فاطلب هذا النعيمَ بالعملِ الصالح، فثمارُ الجنّةِ متراكبةٌ كثيرة، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الثمارِ المتراكبة."},"action":{"text":"تأمّل نعيمَ أصحابِ اليمين: وطلحٍ منضودٍ — أي شجرِ طلحٍ (أو موزٍ) متراكبِ الثمرِ منضودٍ بعضه فوق بعضٍ من أعلاه إلى أسفله، محمّلٍ بالثمار «وطلح منضود»؛ ففي هذا بيانُ نعيمِ أصحابِ اليمينِ في الطلحِ المنضودِ المحمّلِ بالثمار؛ فشجرهم مثقلٌ بالثمرِ المتراكب؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ لها طلعٌ نضيد؛ قطوفها دانية؛ وذُلِّلت قطوفها تذليلًا؛ فثمارُ الجنّةِ متراكبةٌ كثيرةٌ قريبة؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الثمارِ المتراكبةِ دأبك."}},{"n":30,"reflection":{"text":"«وظل ممدود» — وظلٍّ دائمٍ ممتدٍّ لا ينقطع؛ ففي هذا بيانُ نعيمِ الجنّةِ من الظلِّ الدائم؛ فاطلب هذا النعيمَ بالعملِ الصالح، فظلُّ الجنّةِ دائمٌ لا يزول، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الظلِّ الدائم."},"action":{"text":"تأمّل نعيمَ الظلِّ الممدود: وأصحابُ اليمين في ظلٍّ ممدودٍ — أي دائمٍ ممتدٍّ لا ينقطع ولا يزول ولا تنسخه شمس؛ فظلُّهم دائمٌ سابغ «وظل ممدود»؛ ففي هذا بيانُ نعيمِ أصحابِ اليمينِ في الظلِّ الدائمِ الممتد؛ فظلُّ جنّتهم دائمٌ لا يزول؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ وندخلهم ظلًّا ظليلًا؛ أُكُلها دائمٌ وظلّها؛ متّكئين فيها على الأرائكِ لا يرون فيها شمسًا ولا زمهريرًا؛ فظلُّ الجنّةِ دائمٌ سابغٌ لا يزول ولا ينقطع؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الظلِّ الدائمِ دأبك."}},{"n":31,"reflection":{"text":"«وماء مسكوب» — وماءٍ جارٍ مصبوبٍ دائمًا؛ ففي هذا بيانُ نعيمِ الجنّةِ من الماءِ الجاري؛ فاطلب هذا النعيمَ بالعملِ الصالح، فماءُ الجنّةِ جارٍ دائمٌ لا ينقطع، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الماءِ الجاري."},"action":{"text":"تأمّل نعيمَ الماءِ المسكوب: وأصحابُ اليمين في ماءٍ مسكوبٍ — أي جارٍ مصبوبٍ دائمًا، يجري حيث شاؤوا، لا ينقطع ولا يحتاج إلى استقاء «وماء مسكوب»؛ ففي هذا بيانُ نعيمِ أصحابِ اليمينِ في الماءِ الجاري المصبوبِ الدائم؛ فماؤهم جارٍ دائمٌ لا ينقطع؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ فيها أنهارٌ من ماءٍ غيرِ آسن؛ فيهما عينان تجريان؛ فيها عينٌ جارية؛ فماءُ الجنّةِ جارٍ دائمٌ عذبٌ لا ينقطع؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الماءِ الجاري دأبك."}},{"n":32,"reflection":{"text":"«وفاكهة كثيرة» — وفاكهةٍ كثيرةٍ متنوّعة؛ ففي هذا بيانُ سعةِ نعيمِ الجنّةِ من الفاكهة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فثمارُ الجنّةِ كثيرةٌ متنوّعة، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الفاكهةِ الكثيرة."},"action":{"text":"تأمّل سعةَ فاكهةِ الجنّة: وأصحابُ اليمين في فاكهةٍ كثيرةٍ متنوّعةِ الأصنافِ والألوانِ والطعوم؛ فلهم من الفاكهةِ ما لا يُحصى «وفاكهة كثيرة»؛ ففي هذا بيانُ سعةِ نعيمِ أصحابِ اليمينِ من الفاكهةِ الكثيرة؛ فلهم فاكهةٌ كثيرةٌ متنوّعة؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ ولهم فيها من كلِّ الثمرات؛ وفاكهةٍ ممّا يتخيّرون؛ فيها فاكهةٌ ونخلٌ ورمّان؛ فثمارُ الجنّةِ كثيرةٌ متنوّعةٌ لذيذة؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الفاكهةِ الكثيرةِ دأبك."}},{"n":33,"reflection":{"text":"«لا مقطوعة ولا ممنوعة» — لا تنقطع في وقتٍ ولا تُمنَع عمّن أرادها؛ ففي هذا بيانُ دوامِ نعيمِ الجنّةِ وسهولتِه؛ فاطلب هذا النعيمَ الدائمَ بالعملِ الصالح، فنعيمُ الجنّةِ دائمٌ لا ينقطع ولا يُمنَع، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الدائمِ الذي لا ينقطع."},"action":{"text":"تأمّل دوامَ نعيمِ الجنّة: فاكهةُ أصحابِ اليمينِ لا مقطوعةٍ — أي لا تنقطع في وقتٍ من الأوقاتِ كفاكهةِ الدنيا التي لها مواسم؛ ولا ممنوعةٍ — أي لا تُمنَع عمّن أرادها بثمنٍ أو بُعدٍ أو شوك، بل هي مبذولةٌ دائمة «لا مقطوعة ولا ممنوعة»؛ ففي هذا بيانُ دوامِ فاكهةِ الجنّةِ وسهولةِ تناولها؛ فهي دائمةٌ غيرُ منقطعةٍ ولا ممنوعة؛ فاطلب أنت هذا النعيمَ الدائمَ بالعملِ الصالح؛ أُكُلها دائمٌ وظلّها؛ عطاءً غيرَ مجذوذ؛ وذُلِّلت قطوفها تذليلًا؛ فنعيمُ الجنّةِ دائمٌ لا ينقطع ولا يُمنَع؛ فاعمل للجنّةِ ونعيمها الدائمِ بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيمَ الدائم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الدائمِ دأبك."}},{"n":34,"reflection":{"text":"«وفرش مرفوعة» — وفرشٍ عاليةٍ مرتفعةٍ (أو أزواجٍ رفيعاتِ القدر)؛ ففي هذا بيانُ نعيمِ الجنّةِ من الفرشِ العالية؛ فاطلب هذا النعيمَ بالعملِ الصالح، فنعيمُ الجنّةِ رفيعٌ عالٍ، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ الرفيعِ العالي."},"action":{"text":"تأمّل نعيمَ الفرشِ المرفوعة: وأصحابُ اليمين على فرشٍ مرفوعةٍ — أي عاليةٍ مرتفعةِ القدرِ والمكان، مبطّنةٍ فاخرة؛ أو المرادُ الأزواجُ رفيعاتُ القدرِ والحسن «وفرش مرفوعة»؛ ففي هذا بيانُ نعيمِ أصحابِ اليمينِ على الفرشِ العاليةِ الفاخرة، أو بالأزواجِ الرفيعات؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ متّكئين على فرشٍ بطائنها من إستبرق؛ وفُرُشٍ مرفوعة؛ متّكئين على رفرفٍ خضرٍ وعبقريٍّ حسان؛ فنعيمُ الجنّةِ رفيعٌ عالٍ فاخر؛ فاعمل للجنّةِ ونعيمها الرفيعِ بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ الرفيعِ العالي دأبك."}},{"n":35,"reflection":{"text":"«إنا أنشأناهن إنشاء» — إنا أنشأنا نساءَ الجنّةِ (الحورَ) إنشاءً جديدًا بديعًا؛ ففي هذا بيانُ كمالِ خلقِ أزواجِ الجنّة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فأزواجُ الجنّةِ خلقٌ بديعٌ كامل، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الأزواجِ المُنشَآتِ إنشاءً بديعًا."},"action":{"text":"تأمّل كمالَ خلقِ أزواجِ الجنّة: إنا أنشأنا نساءَ الجنّةِ (الحورَ، أو نساءَ الدنيا اللاتي يُعِدن) إنشاءً جديدًا بديعًا كاملًا، على أحسنِ صورةٍ وأكملِ خلق «إنا أنشأناهن إنشاء»؛ ففي هذا بيانُ كمالِ خلقِ أزواجِ الجنّةِ وإنشائهنّ إنشاءً بديعًا؛ فأنشأهنّ الله خلقًا كاملًا؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ فجعلناهنّ أبكارًا؛ إنا خلقناهنّ خلقًا فجعلناهنّ أبكارًا؛ فأزواجُ الجنّةِ خلقٌ بديعٌ كاملٌ على أحسنِ صورة؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الأزواجِ المُنشَآتِ إنشاءً بديعًا دأبك."}},{"n":36,"reflection":{"text":"«فجعلناهن أبكارا» — فجعلناهنّ أبكارًا عذارى؛ ففي هذا بيانُ طهارةِ أزواجِ الجنّة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فأزواجُ الجنّةِ أبكارٌ طاهرات، فاعمل له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الأزواجِ الأبكارِ الطاهرات."},"action":{"text":"تأمّل طهارةَ أزواجِ الجنّة: فجعلنا نساءَ الجنّةِ أبكارًا — أي عذارى لم يمسّهنّ أحد، كلّما أتاهنّ أزواجهنّ وجدوهنّ أبكارًا «فجعلناهن أبكارا»؛ ففي هذا بيانُ طهارةِ أزواجِ الجنّةِ وكونهنّ أبكارًا؛ فهنّ عذارى طاهرات؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ لم يطمثهنّ إنسٌ قبلهم ولا جانّ؛ وأزواجٌ مطهّرة؛ فأزواجُ الجنّةِ أبكارٌ طاهراتٌ عفيفات؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الأزواجِ الأبكارِ الطاهراتِ دأبك."}},{"n":37,"reflection":{"text":"«عربا أترابا» — متحبّباتٍ إلى أزواجهنّ، مستوياتٍ في السنّ؛ ففي هذا بيانُ كمالِ أزواجِ الجنّة؛ فاطلب هذا النعيمَ بالعملِ الصالح، فأزواجُ الجنّةِ كاملاتُ الحسنِ والمحبّة، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنعيمِ الجنّةِ من الأزواجِ الكاملاتِ المتحبّبات."},"action":{"text":"تأمّل كمالَ أزواجِ الجنّة: نساءُ الجنّةِ عُرُبًا — أي متحبّباتٍ إلى أزواجهنّ، عاشقاتٍ لهم، حسناتِ التبعّل؛ أترابًا — أي مستوياتٍ في السنِّ، متساوياتٍ في الحسنِ والجمال، بناتِ ثلاثٍ وثلاثين «عربا أترابا»؛ ففي هذا بيانُ كمالِ أزواجِ الجنّةِ في المحبّةِ والتبعّلِ واستواءِ السنّ؛ فهنّ متحبّباتٌ متساويات؛ فاطلب أنت هذا النعيمَ بالعملِ الصالح؛ وكواعبَ أترابًا؛ فجعلناهنّ أبكارًا عُرُبًا أترابًا؛ فأزواجُ الجنّةِ كاملاتُ الحسنِ والمحبّةِ والشباب؛ فاعمل للجنّةِ ونعيمها بالعملِ الصالح؛ فمن عمل صالحًا نال هذا النعيم، ومن أساء حُرِمه؛ فاجعل العملَ لنعيمِ الجنّةِ من الأزواجِ الكاملاتِ المتحبّباتِ دأبك."}},{"n":38,"reflection":{"text":"«لأصحاب اليمين» — هذا النعيمُ لأصحابِ اليمين؛ ففي هذا بيانُ أنّ هذا النعيمَ جزاءُ أصحابِ اليمين؛ فاعمل لتكون من أصحابِ اليمينِ فتنال هذا النعيم، فالنعيمُ لأصحابِ اليمين، فاجتهد لتكون منهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكونَ من أصحابِ اليمينِ فتنال نعيمهم."},"action":{"text":"تأمّل أنّ النعيمَ لأصحابِ اليمين: هذا النعيمُ المذكورُ (من السدرِ والطلحِ والظلِّ والماءِ والفاكهةِ والفرشِ والأزواج) مُعَدٌّ لأصحابِ اليمينِ جزاءً لهم «لأصحاب اليمين»؛ ففي هذا بيانُ أنّ هذا النعيمَ العظيمَ جزاءُ أصحابِ اليمين؛ فأُعِدّ لهم بإيمانهم وأعمالهم؛ فاعمل أنت لتكون من أصحابِ اليمينِ فتنال هذا النعيم؛ فروحٌ وريحانٌ وجنّةُ نعيم؛ فسلامٌ لك من أصحابِ اليمين؛ أولئك أصحابُ الميمنة؛ فالنعيمُ لأصحابِ اليمينِ السعداء؛ فاجتهد بالإيمانِ والعملِ الصالحِ لتكون منهم؛ فمن عمل صالحًا كان منهم ونال نعيمهم، ومن أساء حُرِم؛ فاجعل العملَ لتكونَ من أصحابِ اليمينِ فتنال نعيمهم دأبك."}}]},{"title":"كثرةُ أصحابِ اليمينِ وعذابُ أصحابِ الشمالِ وإنكارُهم البعث","range":[39,56],"theme":"أصحابُ اليمينِ ثلّةٌ من الأولين وثلّةٌ من الآخرين، وأصحابُ الشمالِ في سمومٍ وحميمٍ وظلٍّ من يحمومٍ لا باردٍ ولا كريم؛ كانوا مترفين مصرّين على الحنثِ العظيمِ منكرين للبعثِ «أئذا متنا وكنا ترابا»، فيُردُّ عليهم بجمعِ الأوّلين والآخرين، ثم أكلهم من الزقّومِ وشربهم الحميمَ نزلًا يومَ الدين","verses":[{"n":39,"reflection":{"text":"«ثلة من الأولين» — أصحابُ اليمين جماعةٌ كثيرةٌ من الأمم الأولى؛ ففي هذا بيانُ كثرةِ أصحابِ اليمين من الأولين؛ فاحرص أن تكون من أصحابِ اليمين الكثيرين، فأصحابُ اليمين كثيرون من الأمم، فاعمل لتكون منهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على أن تكون من أصحابِ اليمين، والعملُ لذلك."},"action":{"text":"تأمّل كثرةَ أصحابِ اليمين من الأولين: أصحابُ اليمين ثلّةٌ — أي جماعةٌ كثيرةٌ — من الأمم الأولين (من الأمم السابقة، أو من صدرِ هذه الأمّة) «ثلة من الأولين»؛ ففي هذا بيانُ أنّ أصحابَ اليمينِ كثيرون من الأمم الأولى؛ فكان فيهم كثرةٌ منهم؛ فاحرص أنت أن تكون من أصحابِ اليمينِ الكثيرين؛ فأصحابُ اليمينِ صنفٌ كثيرٌ من أهلِ الجنّة؛ ثلّةٌ من الأولين وقليلٌ من الآخرين (في السابقين)، وأمّا أصحابُ اليمينِ فثلّةٌ من الأولين وثلّةٌ من الآخرين؛ فاعمل بالإيمانِ والعملِ الصالحِ لتكون منهم؛ فمن عمل صالحًا كان منهم، ومن أساء حُرِم؛ فاجعل الحرصَ على أن تكون من أصحابِ اليمينِ والعملَ لذلك دأبك."}},{"n":40,"reflection":{"text":"«وثلة من الآخرين» — وجماعةٌ كثيرةٌ من الأمم الآخرة (أصحاب اليمين)؛ ففي هذا بيانُ كثرةِ أصحابِ اليمين في الآخرين؛ فاحرص أن تكون منهم، فأصحابُ اليمين كثيرون من الأولين والآخرين، فاعمل لتكون منهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على أن تكون من أصحابِ اليمين من الآخرين، والعملُ لذلك."},"action":{"text":"تأمّل كثرةَ أصحابِ اليمين في الآخرين: أصحابُ اليمين ثلّةٌ — أي جماعةٌ كثيرةٌ — من الأمم الآخرين (من آخرِ الأمم، أو من آخرِ هذه الأمّة)؛ فهم كثيرون في الآخرين كما في الأولين «وثلة من الآخرين»؛ ففي هذا بيانُ أنّ أصحابَ اليمينِ كثيرون من الأمم الآخرة أيضًا؛ فبخلافِ السابقين (قليلٌ من الآخرين)، أصحابُ اليمينِ كثيرون من الأولين والآخرين؛ فاحرص أنت أن تكون منهم؛ فبابُ أصحابِ اليمينِ واسعٌ يسعُ الكثيرين؛ فأصحابُ اليمينِ ما أصحابُ اليمين؛ فاعمل بالإيمانِ والعملِ الصالحِ لتكون منهم؛ فمن عمل صالحًا كان منهم، ومن أساء حُرِم؛ فاجعل الحرصَ على أن تكون من أصحابِ اليمينِ والعملَ لذلك دأبك."}},{"n":41,"reflection":{"text":"«وأصحاب الشمال ما أصحاب الشمال» — وأصحابُ الشمال ما أسوأَ حالهم؛ ففي هذا تهويلُ شأنِ أصحابِ الشمال؛ فاحذر أن تكون من أصحابِ الشمالِ الأشقياء، فحالهم سيّئٌ مهول، فاجتنب أعمالهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن تكون من أصحابِ الشمال، واجتنابُ أعمالهم."},"action":{"text":"تأمّل تهويلَ شأنِ أصحابِ الشمال: وأصحابُ الشمال — وهم الصنفُ الثالثُ من الناس، أهلُ الشقاءِ والنار — ما أصحابُ الشمال؟ استفهامُ تهويلٍ وتفظيعٍ لسوءِ حالهم وعذابهم «وأصحاب الشمال ما أصحاب الشمال»؛ ففي هذا تهويلُ شأنِ أصحابِ الشمالِ وسوءِ حالهم؛ فلهم شأنٌ سيّئٌ مهولٌ من العذاب؛ فاحذر أنت أن تكون من أصحابِ الشمالِ الأشقياء؛ فأصحابُ الشمالِ في سمومٍ وحميم؛ وأصحابُ المشأمةِ ما أصحابُ المشأمة؛ فإنهم لهم شأنٌ سيّئٌ مهول؛ فاجتنب أعمالهم من الكفرِ والترفِ والإصرارِ على المعاصي وإنكارِ البعث؛ فمن اجتنبها نجا، ومن عملها هلك؛ فاجعل الحذرَ من أن تكون منهم واجتنابَ أعمالهم دأبك."}},{"n":42,"reflection":{"text":"«في سموم وحميم» — في ريحٍ حارّةٍ نافذةٍ وماءٍ حارٍّ شديد؛ ففي هذا بيانُ عذابِ أصحابِ الشمال؛ فاحذر عذابَ النار بالإيمانِ والعملِ الصالح، فعذابُ النارِ شديد، فاجتنب أسبابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النار، واجتنابُ أسبابه."},"action":{"text":"تأمّل عذابَ أصحابِ الشمال: أصحابُ الشمال في سمومٍ — أي ريحٍ حارّةٍ تنفذ في المسامّ؛ وحميمٍ — أي ماءٍ حارٍّ متناهٍ في الحرارةِ يُسقَونه ويُصبُّ على رؤوسهم «في سموم وحميم»؛ ففي هذا بيانُ عذابِ أصحابِ الشمالِ بالسمومِ والحميم؛ فهم في حرٍّ نافذٍ وماءٍ حميم؛ فاحذر أنت عذابَ النارِ بالإيمانِ والعملِ الصالح؛ يُصبُّ من فوقِ رؤوسهم الحميم؛ وإن يستغيثوا يُغاثوا بماءٍ كالمهل؛ يطوفون بينها وبين حميمٍ آن؛ فعذابُ النارِ شديدٌ من كلِّ وجه؛ فاجتنب أسبابَ النارِ من الكفرِ والمعاصي؛ فمن اجتنبها نجا، ومن ارتكبها هلك؛ فاجعل الحذرَ من عذابِ النارِ واجتنابَ أسبابه دأبك."}},{"n":43,"reflection":{"text":"«وظل من يحموم» — وظلٍّ من دخانٍ أسودَ شديدِ السواد؛ ففي هذا بيانُ عذابِ أصحابِ الشمال؛ فاحذر عذابَ النار بالإيمانِ والعملِ الصالح، فظلُّ النارِ دخانٌ لا راحةَ فيه، فاجتنب أسبابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النار، والعملُ لظلِّ الجنّةِ الممدود."},"action":{"text":"تأمّل عذابَ أصحابِ الشمال: أصحابُ الشمال في ظلٍّ من يحمومٍ — أي دخانٍ أسودَ شديدِ السوادِ والحرارة، يُظِلُّهم لكنه لا يُريحهم، بخلافِ ظلِّ أصحابِ اليمينِ الممدود «وظل من يحموم»؛ ففي هذا بيانُ عذابِ أصحابِ الشمالِ في ظلِّ الدخانِ الأسود؛ فظلُّهم دخانٌ حارٌّ لا راحةَ فيه؛ فاحذر أنت عذابَ النارِ بالإيمانِ والعملِ الصالح؛ انطلقوا إلى ظلٍّ ذي ثلاثِ شعب، لا ظليلٍ ولا يغني من اللهب؛ فقابل بين ظلِّ أصحابِ اليمينِ الممدودِ وظلِّ أصحابِ الشمالِ من اليحموم؛ فاعمل لظلِّ الجنّةِ الممدودِ بالطاعة؛ فمن آمن وعمل صالحًا نال ظلَّ الجنّة، ومن كفر صار إلى ظلِّ اليحموم؛ فاجعل الحذرَ من عذابِ النارِ والعملَ لظلِّ الجنّةِ الممدودِ دأبك."}},{"n":44,"reflection":{"text":"«لا بارد ولا كريم» — ذلك الظلُّ لا باردٍ فيُستراح إليه ولا كريمٍ حسنِ المنظر؛ ففي هذا بيانُ تمامِ سوءِ عذابهم؛ فاحذر عذابًا لا راحةَ فيه بالإيمانِ والعملِ الصالح، فعذابُ النارِ لا خيرَ فيه، فاجتنب أسبابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابٍ لا راحةَ فيه، واجتنابُ أسبابه."},"action":{"text":"تأمّل تمامَ سوءِ عذابهم: ظلُّ اليحمومِ الذي يُظِلُّ أصحابَ الشمالِ لا باردٍ — أي ليس فيه بردٌ ولا راحةٌ يُستراح إليها؛ ولا كريمٍ — أي ليس حسنَ المنظرِ ولا نافعًا ولا كريمَ الطبع، بل هو حارٌّ قبيحٌ منتن «لا بارد ولا كريم»؛ ففي هذا بيانُ تمامِ سوءِ عذابِ أصحابِ الشمال، فظلُّهم لا برودةَ فيه ولا خير؛ فلا راحةَ فيه ولا نفع؛ فاحذر أنت عذابًا لا راحةَ فيه بالإيمانِ والعملِ الصالح؛ لا يذوقون فيها بردًا ولا شرابًا إلا حميمًا وغسّاقًا؛ فعذابُ النارِ لا خيرَ فيه ولا راحة؛ فاجتنب أسبابَ النارِ من الكفرِ والمعاصي؛ فمن اجتنبها نجا، ومن ارتكبها هلك؛ فاجعل الحذرَ من عذابٍ لا راحةَ فيه واجتنابَ أسبابه دأبك."}},{"n":45,"reflection":{"text":"«إنهم كانوا قبل ذلك مترفين» — إنّ أصحابَ الشمال كانوا في الدنيا منعّمين مُقبِلين على الشهوات؛ ففي هذا بيانُ أنّ الترفَ والغفلةَ سببُ هلاكهم؛ فاحذر أن يشغلك الترفُ عن الآخرة، فالترفُ الغافلُ سبيلُ الهلاك، فلا تركن إليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الترفِ الشاغلِ عن الآخرة، والاعتدالُ في النعيم."},"action":{"text":"تأمّل سببَ هلاكهم الأول: إنّ أصحابَ الشمال كانوا قبل ذلك (في الدنيا) مترفين — أي منعّمين متروّهين، أبطرتهم النعمةُ فأقبلوا على الشهواتِ واللذّاتِ وأعرضوا عن طاعةِ الله «إنهم كانوا قبل ذلك مترفين»؛ ففي هذا بيانُ أنّ الترفَ والانغماسَ في الشهواتِ والغفلةَ عن الآخرةِ من أسبابِ هلاكهم؛ فأبطرتهم النعمةُ فكفروا؛ فاحذر أنت أن يشغلك الترفُ والنعيمُ عن طاعةِ الله والاستعدادِ للآخرة؛ وما أرسلنا في قريةٍ من نذيرٍ إلا قال مترفوها إنا بما أُرسِلتم به كافرون؛ حتى إذا أخذنا مترفيهم بالعذابِ إذا هم يجأرون؛ فالترفُ الغافلُ عن اللهِ سبيلُ الهلاك؛ فاشكر النعمةَ واعتدل فيها ولا تركن إليها؛ فمن شكر النعمةَ ولم تشغله نجا، ومن أبطرته هلك؛ فاجعل الحذرَ من الترفِ الشاغلِ والاعتدالَ في النعيمِ دأبك."}},{"n":46,"reflection":{"text":"«وكانوا يصرون على الحنث العظيم» — وكانوا يُقيمون على الذنبِ العظيم (الشركِ) لا يتوبون؛ ففي هذا بيانُ أنّ الإصرارَ على الشركِ والذنبِ سببُ هلاكهم؛ فاحذر الإصرارَ على الذنبِ وبادر بالتوبة، فالإصرارُ على الذنبِ سبيلُ الهلاك، فتب إلى الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الإصرارِ على الذنب، والمبادرةُ بالتوبة."},"action":{"text":"تأمّل سببَ هلاكهم الثاني: وكانوا يُصِرّون على الحنثِ العظيم — أي يُقيمون ويداومون على الذنبِ العظيمِ (وهو الشركُ بالله، أو اليمينُ الغموسُ، أو عظائمُ الذنوب) لا يتوبون منه ولا يقلعون عنه «وكانوا يصرون على الحنث العظيم»؛ ففي هذا بيانُ أنّ الإصرارَ على الشركِ والذنبِ العظيمِ من أسبابِ هلاكهم؛ فأصرّوا على الكفرِ حتى ماتوا عليه؛ فاحذر أنت الإصرارَ على الذنب، وبادر بالتوبةِ كلّما أذنبت؛ ولم يُصِرّوا على ما فعلوا وهم يعلمون؛ فالإصرارُ على الذنبِ سبيلُ الهلاك، والتوبةُ سبيلُ النجاة؛ فتب إلى الله من كلِّ ذنبٍ ولا تُصِرّ؛ فمن تاب ولم يُصِرّ نجا، ومن أصرّ هلك؛ فاجعل تركَ الإصرارِ على الذنبِ والمبادرةَ بالتوبةِ دأبك."}},{"n":47,"reflection":{"text":"«وكانوا يقولون أئذا متنا وكنا ترابا وعظاما أإنا لمبعوثون» — وكانوا يُنكِرون البعثَ مستبعِدين إحياءهم بعد الموتِ والبلى؛ ففي هذا بيانُ أنّ إنكارَ البعثِ سببُ هلاكهم؛ فأيقن بالبعثِ ولا تستبعده، فالبعثُ حقٌّ على الله يسير، فاستعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ وتركُ استبعاده، والاستعدادُ له."},"action":{"text":"تأمّل سببَ هلاكهم الثالث: وكانوا يقولون منكرين مستبعدين: أئذا متنا وكنا ترابًا وعظامًا (باليةً) أئنا لمبعوثون؟ — أي أنُحيا بعد الموتِ والبلى والتفتّتِ ترابًا؟ استبعادًا وإنكارًا للبعث «أئذا متنا وكنا ترابا وعظاما أإنا لمبعوثون»؛ ففي هذا بيانُ أنّ إنكارَ البعثِ واستبعادَه من أسبابِ هلاكهم؛ فأنكروا البعثَ فكذّبوا الرسل؛ فأيقن أنت بالبعثِ ولا تستبعده؛ قل يُحييها الذي أنشأها أوّلَ مرّة؛ أفعيينا بالخلقِ الأول؛ وضرب لنا مثلًا ونسي خلقه؛ فالبعثُ حقٌّ على الله يسير، والذي بدأ الخلقَ قادرٌ على إعادته؛ فاستعدّ للبعثِ بالإيمانِ والعملِ الصالح؛ فمن أيقن بالبعثِ استعدّ له، ومن أنكره هلك؛ فاجعل اليقينَ بالبعثِ وتركَ استبعادِه والاستعدادَ له دأبك."}},{"n":48,"reflection":{"text":"«أوآباؤنا الأولون» — أوَ يُبعَث آباؤنا الأوّلون الذين ماتوا من قبل؟ — زيادةً في الإنكار؛ ففي هذا بيانُ إمعانهم في إنكارِ البعث؛ فأيقن ببعثِ الأوّلين والآخرين، فالله يجمع الأوّلين والآخرين، فاستعدّ لذلك اليوم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ ببعثِ جميعِ الخلقِ الأوّلين والآخرين، والاستعدادُ لذلك."},"action":{"text":"تأمّل إمعانهم في الإنكار: أوَ آباؤنا الأوّلون — أي أوَ يُبعَث آباؤنا الأقدمون الذين ماتوا وتقادم عهدهم وصاروا ترابًا؟ زادوا في الإنكارِ والاستبعادِ فاستبعدوا بعثَ من تقادم موتهم «أوآباؤنا الأولون»؛ ففي هذا بيانُ إمعانهم في إنكارِ البعثِ واستبعادهم بعثَ الأوّلين؛ فأنكروا بعثهم وبعثَ آبائهم؛ فأيقن أنت ببعثِ جميعِ الخلقِ من الأوّلين والآخرين؛ قل إنّ الأوّلين والآخرين لمجموعون؛ يومَ يجمعكم ليومِ الجمع؛ فالله قادرٌ على جمعِ الأوّلين والآخرين وبعثهم؛ فاستعدّ لذلك اليومِ العظيمِ بالإيمانِ والعمل؛ فمن أيقن به استعدّ له، ومن أنكره هلك؛ فاجعل اليقينَ ببعثِ جميعِ الخلقِ والاستعدادَ لذلك دأبك."}},{"n":49,"reflection":{"text":"«قل إن الأولين والآخرين» — قل لهم يا محمد: إنّ الأوّلين من الأمم والآخرين منهم؛ ففي هذا ردٌّ على منكري البعث؛ فأيقن أنّ الله يجمع الخلقَ كلَّهم، فالبعثُ عامٌّ للأوّلين والآخرين، فاستعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يجمع الخلقَ كلَّهم للبعث، والاستعدادُ له."},"action":{"text":"تأمّل الردَّ على منكري البعث: قل يا محمد لهؤلاء المنكرين: إنّ الأوّلين من الخلقِ (الأمم السابقة) والآخرين منهم (الأمم اللاحقة) «قل إن الأولين والآخرين»؛ ففي هذا ردٌّ على من أنكر البعثَ واستبعد بعثَ الأوّلين؛ فيُقرِّر أنّ الجميعَ — أوّلهم وآخرهم — سيُجمَعون؛ فأيقن أنت بأنّ الله يجمع الخلقَ كلَّهم للبعثِ والحساب؛ وحشرناهم فلم نغادر منهم أحدًا؛ وعُرِضوا على ربّك صفًّا؛ فالبعثُ عامٌّ شاملٌ للأوّلين والآخرين لا يفوته أحد؛ فاستعدّ للبعثِ والجمعِ بالإيمانِ والعملِ الصالح؛ فمن أيقن به استعدّ، ومن أنكره هلك؛ فاجعل اليقينَ بأنّ الله يجمع الخلقَ كلَّهم والاستعدادَ لذلك دأبك."}},{"n":50,"reflection":{"text":"«لمجموعون إلى ميقات يوم معلوم» — لمجموعون في وقتٍ محدّدٍ معلومٍ عند الله (يومِ القيامة)؛ ففي هذا بيانُ حتميّةِ جمعِ الخلقِ في يومٍ معلوم؛ فأيقن بيومٍ يُجمَع فيه الخلقُ كلُّهم، فيومُ الجمعِ آتٍ لا محالة، فاستعدّ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بيومِ الجمعِ المعلوم، والاستعدادُ له."},"action":{"text":"تأمّل حتميّةَ الجمع: الأوّلون والآخرون لمجموعون — أي مبعوثون مجموعون للحساب — إلى ميقاتِ يومٍ معلومٍ — أي إلى وقتٍ محدّدٍ معيّنٍ معلومٍ عند الله لا يتقدّم ولا يتأخّر، وهو يومُ القيامة «لمجموعون إلى ميقات يوم معلوم»؛ ففي هذا بيانُ حتميّةِ جمعِ الخلقِ كلِّهم في يومٍ معلومٍ محدّد؛ فلا بدّ من جمعهم في ذلك اليوم؛ فأيقن أنت بيومٍ يُجمَع فيه الخلقُ كلُّهم للحساب؛ ذلك يومٌ مجموعٌ له الناس؛ إنّ يومَ الفصلِ كان ميقاتًا؛ قل إنّ الأوّلين والآخرين لمجموعون؛ فيومُ الجمعِ آتٍ لا محالةَ في وقتٍ معلومٍ عند الله؛ فاستعدّ له بالإيمانِ والعملِ الصالح؛ فمن أيقن به استعدّ، ومن غفل عنه خسر؛ فاجعل اليقينَ بيومِ الجمعِ المعلومِ والاستعدادَ له دأبك."}},{"n":51,"reflection":{"text":"«ثم إنكم أيها الضالون المكذبون» — ثم إنكم أيها الضالّون عن الحقِّ المكذّبون بالبعث؛ ففي هذا خطابُ توبيخٍ للمكذّبين؛ فاحذر الضلالَ والتكذيبَ بالحقّ، فالضلالُ والتكذيبُ سبيلُ العذاب، فاتّبع الحقَّ وصدّق به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الحقِّ والتصديقُ به، والحذرُ من الضلالِ والتكذيب."},"action":{"text":"تأمّل خطابَ التوبيخ: ثم إنكم — يا معشرَ المنكرين — أيها الضالّون عن طريقِ الحقِّ والهدى، المكذّبون بالبعثِ والرسلِ والقرآن «ثم إنكم أيها الضالون المكذبون»؛ ففي هذا خطابُ توبيخٍ وتقريعٍ للضالّين المكذّبين، وبيانُ ما ينتظرهم من العذاب؛ فوصفهم بالضلالِ (فسادِ العلم) والتكذيبِ (فسادِ العمل)؛ فاحذر أنت الضلالَ عن الحقِّ والتكذيبَ به؛ فمن ضلّ وكذّب استحقّ العذاب؛ ومن يُضلِلِ اللهُ فما له من هاد؛ والذين كذّبوا بآياتنا سنستدرجهم؛ فالضلالُ والتكذيبُ بالحقِّ سبيلُ العذابِ والهلاك؛ فاتّبع أنت الحقَّ وصدّق به وأذعن له؛ فمن اتّبع الحقَّ وصدّق نجا، ومن ضلّ وكذّب هلك؛ فاجعل اتّباعَ الحقِّ والتصديقَ به والحذرَ من الضلالِ والتكذيبِ دأبك."}},{"n":52,"reflection":{"text":"«لآكلون من شجر من زقوم» — لآكلون من شجرِ الزقّومِ (أخبثِ الشجرِ وأمرِّه)؛ ففي هذا بيانُ طعامِ أهلِ النار؛ فاحذر عذابَ النار بالإيمانِ والعملِ الصالح، فطعامُ النارِ خبيثٌ مؤذٍ، فاجتنب أسبابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من طعامِ النار، واجتنابُ أسبابِ العذاب."},"action":{"text":"تأمّل طعامَ أهلِ النار: أيها الضالّون المكذّبون لآكلون من شجرٍ من زقّومٍ — أي من الزقّوم، وهو أخبثُ الشجرِ وأمرُّه وأنتنه، ينبت في أصلِ الجحيم، تأكلون منه حتى تملؤوا بطونكم من الجوع «لآكلون من شجر من زقوم»؛ ففي هذا بيانُ طعامِ أهلِ النار من الزقّومِ الخبيث؛ فطعامهم من أخبثِ الشجرِ وأمرِّه؛ فاحذر أنت عذابَ النارِ بالإيمانِ والعملِ الصالح؛ إنّ شجرةَ الزقّومِ طعامُ الأثيم؛ ليس لهم طعامٌ إلا من ضريع، لا يُسمِن ولا يُغني من جوع؛ فطعامُ النارِ خبيثٌ مؤذٍ مرٌّ؛ فاجتنب أسبابَ النار من الكفرِ والتكذيبِ والمعاصي؛ فمن اجتنبها نجا، ومن ارتكبها هلك؛ فاجعل الحذرَ من طعامِ النارِ واجتنابَ أسبابِ العذابِ دأبك."}},{"n":53,"reflection":{"text":"«فمالئون منها البطون» — فمالئون من الزقّومِ بطونكم من شدّةِ الجوع؛ ففي هذا بيانُ شدّةِ عذابِ أهلِ النار؛ فاحذر عذابَ النار بالإيمانِ والعملِ الصالح، فأهلُ النارِ يُضطَرّون لأكلِ الخبيث، فاجتنب أسبابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النار، واجتنابُ أسبابِ العذاب."},"action":{"text":"تأمّل شدّةَ عذابهم: فمالئون من شجرِ الزقّومِ بطونكم — أي تأكلون منه حتى تملؤوا منه بطونكم من شدّةِ الجوعِ الذي يُلجئكم إليه، مع خبثه ومرارته «فمالئون منها البطون»؛ ففي هذا بيانُ شدّةِ عذابِ أهلِ النار، حيث يُضطَرّون من الجوعِ إلى ملءِ بطونهم من الزقّومِ الخبيث؛ فيأكلون منه رغم خبثه لشدّةِ الجوع؛ فاحذر أنت عذابَ النارِ بالإيمانِ والعملِ الصالح؛ فإنهم لآكلون منها فمالئون منها البطون؛ فأهلُ النارِ في جوعٍ وعذابٍ يُلجئهم إلى أكلِ الخبيث؛ فاجتنب أسبابَ النار من الكفرِ والمعاصي؛ فمن اجتنبها نجا، ومن ارتكبها هلك؛ فاجعل الحذرَ من عذابِ النارِ واجتنابَ أسبابه دأبك."}},{"n":54,"reflection":{"text":"«فشاربون عليه من الحميم» — فشاربون على الزقّومِ من الماءِ الحارِّ الشديد؛ ففي هذا بيانُ شدّةِ عذابِ أهلِ النار؛ فاحذر عذابَ النار بالإيمانِ والعملِ الصالح، فشرابُ أهلِ النارِ حميمٌ يُقطّع الأمعاء، فاجتنب أسبابه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من شرابِ النار، واجتنابُ أسبابِ العذاب."},"action":{"text":"تأمّل شرابَ أهلِ النار: فشاربون على أكلِ الزقّومِ من الحميمِ — أي من الماءِ الحارِّ المتناهي في الحرارةِ الذي يُقطِّع أمعاءهم، يشربونه فوق الزقّومِ لما يجدون من العطشِ والحرارة «فشاربون عليه من الحميم»؛ ففي هذا بيانُ شدّةِ عذابِ أهلِ النار بالشربِ من الحميمِ فوق أكلِ الزقّوم؛ فطعامهم زقّومٌ وشرابهم حميم؛ فاحذر أنت عذابَ النارِ بالإيمانِ والعملِ الصالح؛ وسُقوا ماءً حميمًا فقطّع أمعاءهم؛ يُصهَر به ما في بطونهم والجلود؛ فشرابُ أهلِ النارِ حميمٌ يُقطّع الأمعاء؛ فاجتنب أسبابَ النار من الكفرِ والمعاصي؛ فمن اجتنبها نجا، ومن ارتكبها هلك؛ فاجعل الحذرَ من شرابِ النارِ واجتنابَ أسبابه دأبك."}},{"n":55,"reflection":{"text":"«فشاربون شرب الهيم» — فشاربون من الحميمِ شربَ الإبلِ العطاشِ التي لا تروى؛ ففي هذا بيانُ تمامِ عذابهم بالعطشِ الدائم؛ فاحذر عذابَ النار بالإيمانِ والعملِ الصالح، فأهلُ النارِ في عطشٍ لا يُروى، فاجتنب أسبابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ العطشِ في النار، واجتنابُ أسبابه."},"action":{"text":"تأمّل تمامَ عذابِ العطش: فشاربون من الحميمِ شربَ الهيمِ — أي شربَ الإبلِ العطاشِ التي أصابها داءُ الهُيامِ (العطشِ الذي لا يُروى)، فتشرب ولا تروى حتى تهلك؛ فكذلك أهلُ النارِ يشربون الحميمَ ولا يروون «فشاربون شرب الهيم»؛ ففي هذا بيانُ تمامِ عذابِ أهلِ النار بالعطشِ الدائم، فيشربون كشربِ الإبلِ الهيمِ ولا يروون؛ فعطشهم لا ينقطع؛ فاحذر أنت عذابَ النارِ بالإيمانِ والعملِ الصالح؛ وإن يستغيثوا يُغاثوا بماءٍ كالمهلِ يشوي الوجوه؛ فأهلُ النارِ في عطشٍ لا يُروى وعذابٍ لا ينقطع؛ فاجتنب أسبابَ النار من الكفرِ والمعاصي؛ فمن اجتنبها نجا، ومن ارتكبها هلك؛ فاجعل الحذرَ من عذابِ العطشِ في النارِ واجتنابَ أسبابه دأبك."}},{"n":56,"reflection":{"text":"«هذا نزلهم يوم الدين» — هذا الطعامُ والشرابُ ضيافتهم يومَ الجزاء؛ ففي هذا بيانُ سوءِ ضيافةِ أهلِ النار؛ فاحذر أن يكون الزقّومُ والحميمُ نزلك بالإيمانِ والعملِ الصالح، فنزلُ الكفّارِ سوءُ الضيافة، فاعمل لنزلِ الجنّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لنزلِ الجنّةِ الكريم، والحذرُ من نزلِ النار."},"action":{"text":"تأمّل سوءَ ضيافتهم: هذا — الزقّومُ والحميمُ — نزلهم — أي ضيافتهم وما يُهيَّأ لهم عند نزولهم النار — يومَ الدينِ — أي يومَ الجزاءِ والحساب؛ فهذا ما يُقدَّم لهم ضيافةً وهو شرُّ ضيافة «هذا نزلهم يوم الدين»؛ ففي هذا بيانُ سوءِ ضيافةِ أهلِ النار، حيث نزلهم الزقّومُ والحميم، في مقابلِ نزلِ أهلِ الجنّةِ الكريم؛ فبئس النزلُ نزلهم؛ فاحذر أنت أن يكون الزقّومُ والحميمُ نزلك بالإيمانِ والعملِ الصالح؛ نزلًا من غفورٍ رحيم (لأهلِ الجنّة) مقابل نزلٍ من حميم (لأهلِ النار)؛ إنّ الذين آمنوا وعملوا الصالحاتِ كانت لهم جنّاتُ الفردوسِ نزلًا؛ فنزلُ الكفّارِ سوءُ الضيافةِ ونزلُ المؤمنين كرمها؛ فاعمل لنزلِ الجنّةِ الكريمِ بالإيمانِ والعمل؛ فمن آمن وعمل صالحًا نال نزلَ الجنّة، ومن كفر صار إلى نزلِ النار؛ فاجعل العملَ لنزلِ الجنّةِ والحذرَ من نزلِ النارِ دأبك."}}]},{"title":"أدلّةُ البعثِ بالخلقِ والزرعِ والماءِ والنار","range":[57,74],"theme":"إقامةُ الأدلّةِ على البعث: «نحن خلقناكم فلولا تصدقون»، ثم النطفةُ «أأنتم تخلقونه أم نحن الخالقون»، وتقديرُ الموتِ، والنشأةُ الأولى، ثم الزرعُ «أأنتم تزرعونه»، والماءُ «أأنتم أنزلتموه من المزن»، والنارُ «أأنتم أنشأتم شجرتها» تذكرةً ومتاعًا، وختامها «فسبح باسم ربك العظيم»","verses":[{"n":57,"reflection":{"text":"«نحن خلقناكم فلولا تصدقون» — نحن خلقناكم أوّلَ مرّةٍ من العدم، فهلّا تصدّقون بالبعثِ والإعادة؟ ففي هذا دليلُ البعثِ بالخلقِ الأول؛ فأيقن بالبعثِ قياسًا على الخلقِ الأول، فمن قدر على الخلقِ قدر على الإعادة، فصدّق بالبعث.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ استدلالًا بالخلقِ الأول، والتصديقُ به."},"action":{"text":"تأمّل دليلَ البعثِ بالخلقِ الأول: نحن خلقناكم — أيها الناسُ — من العدمِ أوّلَ مرّةٍ ولم تكونوا شيئًا، فلولا — أي فهلّا — تصدّقون بالبعثِ والإعادة؟ فالذي خلقكم ابتداءً قادرٌ على إعادتكم «نحن خلقناكم فلولا تصدقون»؛ ففي هذا إقامةُ الدليلِ على البعثِ بالخلقِ الأول: من قدر على الخلقِ الابتدائيِّ من العدمِ فهو أقدرُ على الإعادة؛ فالإعادةُ أهونُ من البدء؛ فأيقن أنت بالبعثِ قياسًا على الخلقِ الأول؛ وهو الذي يبدأ الخلقَ ثم يعيده وهو أهونُ عليه؛ كما بدأكم تعودون؛ أفعيينا بالخلقِ الأول بل هم في لبسٍ من خلقٍ جديد؛ فمن قدر على الخلقِ الأولِ قدر على الإعادةِ والبعث؛ فصدّق أنت بالبعثِ وأيقن به؛ فمن صدّق بالبعثِ استعدّ له، ومن كذّب هلك؛ فاجعل اليقينَ بالبعثِ استدلالًا بالخلقِ الأولِ والتصديقَ به دأبك."}},{"n":58,"reflection":{"text":"«أفرأيتم ما تمنون» — أفرأيتم النطفةَ التي تُلقونها في الأرحام؟ ففي هذا لفتُ النظرِ إلى أصلِ الخلق؛ فتأمّل بدءَ خلقك من نطفةٍ لتُوقن بقدرةِ الله على البعث، فمن خلقك من نطفةٍ يبعثك، فاعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بأصلِ الخلقِ من النطفة، واليقينُ بقدرةِ الله."},"action":{"text":"تأمّل أصلَ الخلق: أفرأيتم ما تُمنون — أي أخبروني عن النطفةِ (المنيِّ) التي تُلقونها وتصبّونها في أرحامِ النساء «أفرأيتم ما تمنون»؛ ففي هذا لفتُ النظرِ إلى أصلِ خلقِ الإنسانِ من النطفة، تمهيدًا للاستدلالِ على قدرةِ الله على البعث؛ فيسألهم عن هذا الماءِ المهين؛ فتأمّل أنت بدءَ خلقك من نطفةٍ ضعيفةٍ لتُوقن بقدرةِ الله؛ ألم يكُ نطفةً من منيٍّ يُمنى؛ فلينظرِ الإنسانُ ممّ خُلِق، خُلِق من ماءٍ دافق؛ إنا خلقنا الإنسانَ من نطفةٍ أمشاج؛ فمن خلقك من هذه النطفةِ الضعيفةِ قادرٌ على بعثك؛ فاعتبر أنت بأصلِ خلقك واعرف قدرةَ خالقك؛ فمن اعتبر أيقن بالبعث، ومن غفل كذّب؛ فاجعل الاعتبارَ بأصلِ الخلقِ من النطفةِ واليقينَ بقدرةِ الله دأبك."}},{"n":59,"reflection":{"text":"«أأنتم تخلقونه أم نحن الخالقون» — أأنتم تخلقون النطفةَ بشرًا سويًّا أم نحن الخالقون؟ ففي هذا إقامةُ الحجّةِ بأنّ الخلقَ لله وحده؛ فأقرّ بأنّ الخلقَ لله وحده فآمن بقدرته على البعث، فمن انفرد بالخلقِ ينفرد بالإعادة، فأذعن له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بانفرادِ الله بالخلق، واليقينُ بقدرته على البعث."},"action":{"text":"تأمّل إقامةَ الحجّة: أأنتم تخلقون ما تُمنونه (النطفةَ) فتصوّرونه بشرًا سويًّا وتنفخون فيه الروح، أم نحن الخالقون له؟ استفهامُ تقريرٍ وإلزام؛ فليس لهم في خلقه شيء «أأنتم تخلقونه أم نحن الخالقون»؛ ففي هذا إقامةُ الحجّةِ عليهم بأنّ خلقَ الإنسانِ من النطفةِ ليس إليهم بل إلى الله وحده؛ فهم لا يقدرون على تصويرِ النطفةِ ولا إحيائها؛ فأقرّ أنت بأنّ الخلقَ لله وحده لا شريكَ له؛ أم خُلِقوا من غيرِ شيءٍ أم هم الخالقون؛ هل من خالقٍ غيرُ الله؛ فمن انفرد بالخلقِ الابتدائيِّ انفرد بالإعادةِ والبعث؛ فآمن بقدرةِ الله على البعثِ وأذعن له؛ فمن أقرّ بذلك أيقن بالبعث، ومن كابر كذّب؛ فاجعل الإقرارَ بانفرادِ الله بالخلقِ واليقينَ بقدرته على البعثِ دأبك."}},{"n":60,"reflection":{"text":"«نحن قدرنا بينكم الموت وما نحن بمسبوقين» — نحن قدّرنا الموتَ بينكم بمقاديرَ معلومة، وما نحن بعاجزين مغلوبين؛ ففي هذا بيانُ أنّ الموتَ بتقديرِ الله وأنه غيرُ مغلوب؛ فأيقن أنّ الموتَ بيدِ الله والبعثَ في قدرته، فمن قدّر الموتَ يقدر على البعث، فاستعدّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الموتَ والبعثَ بيدِ الله، والاستعدادُ للقاءه."},"action":{"text":"تأمّل تقديرَ الموت: نحن قدّرنا بينكم الموتَ — أي جعلناه بمقاديرَ معلومةٍ وآجالٍ محدّدةٍ لكلِّ أحد، لا يتقدّم ولا يتأخّر؛ وما نحن بمسبوقين — أي بعاجزين مغلوبين، بل نحن قادرون على ما نشاء «نحن قدرنا بينكم الموت وما نحن بمسبوقين»؛ ففي هذا بيانُ أنّ الموتَ بتقديرِ الله وحكمته، وأنه سبحانه غيرُ مغلوبٍ ولا معجَز؛ فالموتُ بيده والبعثُ في قدرته؛ فأيقن أنت بأنّ الموتَ والبعثَ بيدِ الله وحده؛ كلُّ نفسٍ ذائقةُ الموت؛ أينما تكونوا يُدرِككم الموت؛ وما كان اللهُ ليُعجِزه من شيء؛ فمن قدّر الموتَ وأجراه على العبادِ قادرٌ على بعثهم بعده؛ فاستعدّ للموتِ ولقاءِ الله بالإيمانِ والعمل؛ فمن أيقن بذلك استعدّ، ومن غفل خسر؛ فاجعل اليقينَ بأنّ الموتَ والبعثَ بيدِ الله والاستعدادَ للقاءه دأبك."}},{"n":61,"reflection":{"text":"«على أن نبدل أمثالكم وننشئكم في ما لا تعلمون» — على أن نُغيِّر خلقكم وننشئكم نشأةً أخرى لا تعلمونها؛ ففي هذا بيانُ قدرةِ الله على الإنشاءِ والتبديل؛ فأيقن بقدرةِ الله على إعادتك في خلقٍ جديد، فمن قدر على إنشائك ينشئك من جديد، فاستعدّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرةِ الله على الإنشاءِ الجديد، والاستعدادُ للبعث."},"action":{"text":"تأمّل قدرةَ الإنشاء: قدّرنا بينكم الموتَ وما نحن بمغلوبين على أن نُبدِّل أمثالكم — أي نأتي بأمثالكم بدلًا منكم، أو نُغيِّر صفاتكم وخلقكم؛ وننشئكم في ما لا تعلمون — أي ننشئكم نشأةً أخرى وفي صورٍ وأحوالٍ لا تعلمونها «على أن نبدل أمثالكم وننشئكم في ما لا تعلمون»؛ ففي هذا بيانُ قدرةِ الله على تبديلِ الخلقِ وإنشائهم نشأةً جديدةً لا يعلمونها، فكما أنشأهم أوّلًا يُنشئهم آخرًا؛ فقدرتُه على الإنشاءِ الجديدِ ثابتة؛ فأيقن أنت بقدرةِ الله على إعادتك في خلقٍ جديد؛ لقادرين على أن نُبدِّل خيرًا منهم؛ إن يشأ يُذهبكم ويأتِ بخلقٍ جديد؛ ثم أنشأناه خلقًا آخر؛ فمن قدر على إنشائك أوّلًا يقدر على إنشائك ثانيًا؛ فاستعدّ للبعثِ والنشأةِ الأخرى بالإيمانِ والعمل؛ فمن أيقن بذلك استعدّ، ومن كذّب هلك؛ فاجعل اليقينَ بقدرةِ الله على الإنشاءِ الجديدِ والاستعدادَ للبعثِ دأبك."}},{"n":62,"reflection":{"text":"«ولقد علمتم النشأة الأولى فلولا تذكرون» — ولقد علمتم النشأةَ الأولى (خلقكم أوّلَ مرّة)، فهلّا تتذكّرون فتُوقنون بالنشأةِ الآخرة؟ ففي هذا استدلالٌ بالنشأةِ الأولى على الآخرة؛ فتذكّر بدءَ خلقك لتُوقن بالبعث، فمن علم النشأةَ الأولى أيقن بالآخرة، فتذكّر واعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكّرُ والاعتبارُ بالنشأةِ الأولى، واليقينُ بالنشأةِ الآخرة."},"action":{"text":"تأمّل الاستدلالَ بالنشأةِ الأولى: ولقد علمتم النشأةَ الأولى — أي عرفتم كيف خلقكم الله أوّلَ مرّةٍ من نطفةٍ ثم علقةٍ ثم مضغةٍ حتى صرتم بشرًا سويًّا؛ فلولا — أي فهلّا — تذكّرون فتستدلّون بالنشأةِ الأولى على قدرةِ الله على النشأةِ الآخرة (البعث)؟ «ولقد علمتم النشأة الأولى فلولا تذكرون»؛ ففي هذا استدلالٌ بالنشأةِ الأولى المعلومةِ على النشأةِ الآخرةِ المُنكَرة؛ فمن علم الأولى لزمه الإقرارُ بالآخرة، إذ القادرُ على البدءِ قادرٌ على الإعادة؛ فتذكّر أنت بدءَ خلقك لتُوقن بالبعث؛ كما بدأنا أوّلَ خلقٍ نُعيده؛ ثم إذا شاء أنشره؛ قل يُحييها الذي أنشأها أوّلَ مرّة؛ فمن علم النشأةَ الأولى فقد قامت عليه الحجّةُ بالنشأةِ الآخرة؛ فتذكّر واعتبر وأيقن بالبعث؛ فمن تذكّر أيقن، ومن غفل كذّب؛ فاجعل التذكّرَ والاعتبارَ بالنشأةِ الأولى واليقينَ بالآخرةِ دأبك."}},{"n":63,"reflection":{"text":"«أفرأيتم ما تحرثون» — أفرأيتم الأرضَ التي تحرثونها وتُلقون فيها البذر؟ ففي هذا دليلٌ آخرُ على قدرةِ الله؛ فتأمّل الزرعَ لتعرف قدرةَ الله وفضله، فمن أنبت الزرعَ قادرٌ على البعث، فاعتبر واشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بالزرعِ ومعرفةُ قدرةِ الله وفضله، والشكرُ له."},"action":{"text":"تأمّل دليلَ الزرع: أفرأيتم ما تحرثون — أي أخبروني عن الأرضِ التي تحرثونها وتُثيرونها وتُلقون فيها البذرَ رجاءَ نباته «أفرأيتم ما تحرثون»؛ ففي هذا لفتُ النظرِ إلى الزرعِ دليلًا على قدرةِ الله وفضله، وتمهيدًا للاستدلالِ على البعث؛ فيسألهم عن الحرثِ الذي غايةُ صنعهم فيه إلقاءُ البذر؛ فتأمّل أنت الزرعَ وكيف يُنبِته الله؛ فلينظرِ الإنسانُ إلى طعامه، أنا صببنا الماءَ صبًّا ثم شققنا الأرضَ شقًّا فأنبتنا فيها حبًّا؛ يُخرِج به زرعًا مختلفًا ألوانه؛ فمن أنبت الزرعَ من الحبِّ الميّتِ قادرٌ على إخراجِ الموتى من قبورهم؛ فاعتبر بالزرعِ واعرف قدرةَ الله وفضله واشكره؛ فمن اعتبر أيقن وشكر، ومن غفل كفر؛ فاجعل الاعتبارَ بالزرعِ ومعرفةَ قدرةِ الله والشكرَ له دأبك."}},{"n":64,"reflection":{"text":"«أأنتم تزرعونه أم نحن الزارعون» — أأنتم تُنبِتون الزرعَ وتُنمّونه أم نحن الزارعون؟ ففي هذا إقرارٌ بأنّ الإنباتَ لله وحده؛ فأقرّ بأنّ الإنباتَ فضلُ الله لا صنعك، فمن أنبت الزرعَ يقدر على البعث، فأذعن واشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بأنّ الإنباتَ فضلُ الله، والشكرُ له، واليقينُ بقدرته."},"action":{"text":"تأمّل الإقرارَ بأنّ الإنباتَ لله: أأنتم تزرعونه — أي تُنبِتونه وتُنمّونه وتُخرِجونه من الأرض — أم نحن الزارعون المُنبِتون؟ استفهامُ تقريرٍ وإلزام؛ فغايةُ صنعكم إلقاءُ البذر، وأمّا الإنباتُ والإخراجُ فمن الله وحده «أأنتم تزرعونه أم نحن الزارعون»؛ ففي هذا إقامةُ الحجّةِ بأنّ إنباتَ الزرعِ وإنماءَه ليس إليهم بل إلى الله وحده؛ فما عليهم إلا إلقاءُ البذرِ في الأرض؛ فأقرّ أنت بأنّ الإنباتَ فضلُ الله لا صنعك؛ فأنبتنا فيها حبًّا؛ فأخرجنا به أزواجًا من نباتٍ شتّى؛ أإله مع الله؛ فمن قدر على إنباتِ الزرعِ من الحبِّ قادرٌ على بعثِ الموتى؛ فأذعن لله واشكر فضله وأيقن بقدرته على البعث؛ فمن أقرّ بذلك شكر وأيقن، ومن كابر كفر؛ فاجعل الإقرارَ بأنّ الإنباتَ فضلُ الله والشكرَ له واليقينَ بقدرته دأبك."}},{"n":65,"reflection":{"text":"«لو نشاء لجعلناه حطاما فظلتم تفكهون» — لو نشاء لجعلنا الزرعَ محطّمًا هشيمًا، فتظلّون تتعجّبون وتتحسّرون؛ ففي هذا بيانُ أنّ بقاءَ الزرعِ نعمةٌ من الله؛ فاشكر الله على نعمةِ الزرعِ فإنها بمشيئته، فنعمةُ الزرعِ منّةٌ لو شاء سلبها، فاشكر ولا تغترّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الزرعِ وعدمُ الاغترارِ بها، وخشيةُ زوالها."},"action":{"text":"تأمّل أنّ بقاءَ الزرعِ نعمة: لو نشاء لجعلنا الزرعَ — بعد أن أنبتناه وأنعمنا به عليكم — حطامًا — أي هشيمًا محطّمًا يابسًا لا حبَّ فيه ولا نفع؛ فظلتم تفكّهون — أي تتعجّبون وتتحسّرون وتندمون على ما فاتكم، أو تتفكّهون بالقولِ متندّمين «لو نشاء لجعلناه حطاما فظلتم تفكهون»؛ ففي هذا بيانُ أنّ بقاءَ الزرعِ صالحًا نافعًا نعمةٌ من الله لو شاء سلبها؛ فلو شاء أهلكه فتحسّرتم؛ فاشكر أنت الله على نعمةِ الزرعِ وثباتها فإنها بمشيئته؛ ولو نشاء لجعلناه أُجاجًا؛ إنّا لمُغرَمون بل نحن محرومون؛ فنعمةُ الزرعِ منّةٌ من الله لو شاء أزالها في لحظة؛ فاشكرها ولا تغترّ بها، وخفْ زوالها بالكفرِ والمعصية؛ فمن شكرها بقيت وزادت، ومن كفرها زالت؛ فاجعل شكرَ نعمةِ الزرعِ وعدمَ الاغترارِ بها وخشيةَ زوالها دأبك."}},{"n":66,"reflection":{"text":"«إنا لمغرمون» — تقولون عند هلاكِ الزرع: إنا لمُغرَمون مُلزَمون بالغرامةِ والخسارة؛ ففي هذا بيانُ حسرةِ من حُرِم ثمرةَ عمله؛ فاعلم أنّ حفظَ النعمةِ بيدِ الله فاشكره، فالنعمةُ لا تدوم إلا بشكرِ المُنعِم، فاشكر ولا تجزع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على حفظِ النعمة، والصبرُ عند فواتها."},"action":{"text":"تأمّل حسرةَ الحرمان: لو جعل الله زرعكم حطامًا لظللتم تقولون تحسّرًا: إنا لمُغرَمون — أي مُلزَمون بالغرامةِ والخسارةِ ذاهبةٌ نفقتنا، أو مُعذَّبون بذهابِ زرعنا بعد تعبنا فيه «إنا لمغرمون»؛ ففي هذا بيانُ حسرةِ الإنسانِ وجزعه إذا حُرِم ثمرةَ عمله وذهب زرعه؛ فيقول متحسّرًا: خسرنا وذهب تعبنا؛ فاعلم أنت أنّ حفظَ الزرعِ والنعمةِ بيدِ الله وحده، فاشكره على حفظها؛ ونادوا يا مالكُ (حسرةً)؛ يا حسرتى على ما فرّطت؛ فالنعمةُ لا تدوم إلا بشكرِ المُنعِم وطاعته؛ فاشكر الله على نعمه ولا تجزع عند فواتِ شيءٍ منها؛ فمن شكر حُفِظت نعمته، ومن كفر أو جزع خُذِل؛ فاجعل شكرَ الله على حفظِ النعمةِ والصبرَ عند فواتها دأبك."}},{"n":67,"reflection":{"text":"«بل نحن محرومون» — بل نحن محرومون من الرزقِ والخير؛ ففي هذا بيانُ شعورِ المحرومِ بالحرمان؛ فاعلم أنّ الرزقَ بيدِ الله فاطلبه منه بالطاعة، فالرزقُ والحرمانُ بيدِ الله، فاعمل لما يُبارِك رزقك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الرزقِ من الله بالطاعة، والحذرُ من أسبابِ الحرمان."},"action":{"text":"تأمّل شعورَ الحرمان: بل نحن محرومون — أي بل حُرِمنا رزقنا وخيرنا وثمرةَ سعينا، أو حُرِمنا الرزقَ بذنوبنا؛ يقولها الإنسانُ إذا هلك زرعه تحسّرًا وشعورًا بالحرمان «بل نحن محرومون»؛ ففي هذا بيانُ شعورِ المحرومِ بالحرمانِ إذا سُلِبت نعمته؛ فيشعر أنه حُرِم الخير؛ فاعلم أنت أنّ الرزقَ والحرمانَ بيدِ الله وحده، فاطلب الرزقَ منه بالطاعةِ والاستغفار؛ ومن يتّقِ الله يجعل له مخرجًا ويرزقه من حيث لا يحتسب؛ استغفروا ربّكم إنه كان غفّارًا يُرسِلِ السماءَ عليكم مدرارًا؛ فما أصابهم من حرمانٍ فبذنوبهم؛ فما أصابكم من مصيبةٍ فبما كسبت أيديكم؛ فاطلب الرزقَ من الله بالطاعةِ واتّقِ أسبابَ الحرمانِ من المعاصي؛ فمن أطاع بُورِك رزقه، ومن عصى حُرِم؛ فاجعل طلبَ الرزقِ من الله بالطاعةِ والحذرَ من أسبابِ الحرمانِ دأبك."}},{"n":68,"reflection":{"text":"«أفرأيتم الماء الذي تشربون» — أفرأيتم الماءَ العذبَ الذي تشربونه؟ ففي هذا دليلٌ ثالثٌ على قدرةِ الله وفضله؛ فتأمّل نعمةَ الماءِ لتعرف قدرةَ الله وتشكره، فالماءُ نعمةٌ من الله، فاشكرها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بنعمةِ الماء، ومعرفةُ قدرةِ الله، وشكرها."},"action":{"text":"تأمّل دليلَ الماء: أفرأيتم الماءَ الذي تشربون — أي أخبروني عن هذا الماءِ العذبِ الفراتِ الذي تشربونه وتحيون به «أفرأيتم الماء الذي تشربون»؛ ففي هذا لفتُ النظرِ إلى نعمةِ الماءِ دليلًا على قدرةِ الله وفضله، وتمهيدًا للاستدلالِ على البعثِ (إذ يُحيي الأرضَ الميّتةَ بالماء)؛ فيسألهم عن هذا الماءِ الذي به قوامُ حياتهم؛ فتأمّل أنت نعمةَ الماءِ العذبِ وكيف سخّره الله لك؛ وجعلنا من الماءِ كلَّ شيءٍ حي؛ وأنزلنا من السماءِ ماءً طهورًا؛ فلينظرِ الإنسانُ إلى طعامه؛ فالماءُ نعمةٌ عظيمةٌ من الله لا غنى عنها؛ فاعتبر بها واعرف قدرةَ الله وفضله واشكره؛ فمن اعتبر شكر وأيقن، ومن غفل كفر؛ فاجعل الاعتبارَ بنعمةِ الماءِ ومعرفةَ قدرةِ الله وشكرها دأبك."}},{"n":69,"reflection":{"text":"«أأنتم أنزلتموه من المزن أم نحن المنزلون» — أأنتم أنزلتم الماءَ من السحابِ أم نحن المُنزِلون؟ ففي هذا إقرارٌ بأنّ إنزالَ المطرِ لله وحده؛ فأقرّ بأنّ المطرَ فضلُ الله لا صنعك، فمن أنزل الماءَ يقدر على البعث، فأذعن واشكر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بأنّ المطرَ فضلُ الله، والشكرُ له، واليقينُ بقدرته."},"action":{"text":"تأمّل الإقرارَ بأنّ المطرَ لله: أأنتم أنزلتموه من المزنِ — أي من السحابِ — أم نحن المُنزِلون له؟ استفهامُ تقريرٍ وإلزام؛ فليس لهم في إنزالِ المطرِ شيء، بل هو فضلُ الله وحده «أأنتم أنزلتموه من المزن أم نحن المنزلون»؛ ففي هذا إقامةُ الحجّةِ بأنّ إنزالَ المطرِ من السحابِ ليس إليهم بل إلى الله وحده؛ فلا يقدرون على إنزالِ قطرةٍ منه؛ فأقرّ أنت بأنّ المطرَ فضلُ الله لا صنعك؛ أفرأيتم الماءَ الذي تشربون؛ فأنزلنا من السماءِ ماءً فأسقيناكموه وما أنتم له بخازنين؛ وهو الذي يُنزِّل الغيثَ من بعدِ ما قنطوا؛ فمن أنزل الماءَ وأحيا به الأرضَ الميّتةَ قادرٌ على إحياءِ الموتى؛ فأذعن لله واشكر فضله وأيقن بقدرته على البعث؛ فمن أقرّ بذلك شكر وأيقن، ومن كابر كفر؛ فاجعل الإقرارَ بأنّ المطرَ فضلُ الله والشكرَ له واليقينَ بقدرته دأبك."}},{"n":70,"reflection":{"text":"«لو نشاء جعلناه أجاجا فلولا تشكرون» — لو نشاء جعلنا الماءَ العذبَ ملحًا مرًّا، فهلّا تشكرون على عذوبته؟ ففي هذا بيانُ أنّ عذوبةَ الماءِ نعمةٌ توجب الشكر؛ فاشكر الله على عذوبةِ الماءِ فإنها بمشيئته، فعذوبةُ الماءِ منّةٌ لو شاء سلبها، فاشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على عذوبةِ الماء، والحذرُ من كفرانِ النعمة."},"action":{"text":"تأمّل أنّ عذوبةَ الماءِ نعمة: لو نشاء جعلناه — أي الماءَ العذبَ الذي تشربون — أجاجًا — أي ملحًا مرًّا شديدَ الملوحةِ لا يُشرَب ولا يُنتفَع به؛ فلولا — أي فهلّا — تشكرون الله على أن جعله عذبًا فراتًا؟ «لو نشاء جعلناه أجاجا فلولا تشكرون»؛ ففي هذا بيانُ أنّ عذوبةَ الماءِ نعمةٌ عظيمةٌ من الله توجب الشكر، ولو شاء جعله أُجاجًا؛ فبقاؤه عذبًا فضلٌ منه؛ فاشكر أنت الله على عذوبةِ الماءِ فإنها بمشيئته وحده؛ وما يستوي البحران هذا عذبٌ فراتٌ سائغٌ شرابه وهذا ملحٌ أُجاج؛ لئن شكرتم لأزيدنّكم؛ فعذوبةُ الماءِ منّةٌ من الله لو شاء سلبها في لحظة؛ فاشكرها بالطاعةِ واحذر كفرانها بالمعصية؛ فمن شكرها زادت، ومن كفرها زالت؛ فاجعل شكرَ الله على عذوبةِ الماءِ والحذرَ من كفرانِ النعمةِ دأبك."}},{"n":71,"reflection":{"text":"«أفرأيتم النار التي تورون» — أفرأيتم النارَ التي تُخرِجونها بالقدح (من الشجرِ الأخضر)؟ ففي هذا دليلٌ رابعٌ على قدرةِ الله؛ فتأمّل نعمةَ النارِ لتعرف قدرةَ الله وفضله، فالنارُ نعمةٌ ومنفعة، فاشكرها واعتبر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بنعمةِ النار، ومعرفةُ قدرةِ الله، وشكرها."},"action":{"text":"تأمّل دليلَ النار: أفرأيتم النارَ التي تُورون — أي تُخرِجونها وتُوقِدونها بالقدحِ من الزندِ (من الشجرِ الأخضرِ الذي فيه الماء) «أفرأيتم النار التي تورون»؛ ففي هذا لفتُ النظرِ إلى نعمةِ النارِ دليلًا على قدرةِ الله وفضله، وفيه تنبيهٌ على البعث (إخراجُ النارِ من الشجرِ الأخضرِ الرطبِ كإخراجِ الحيِّ من الميّت)؛ فيسألهم عن هذه النارِ التي ينتفعون بها؛ فتأمّل أنت نعمةَ النارِ وكيف أودعها الله في الشجر؛ الذي جعل لكم من الشجرِ الأخضرِ نارًا فإذا أنتم منه توقدون؛ فمن أخرج النارَ من الشجرِ الأخضرِ (وهما ضدّان) قادرٌ على إخراجِ الحيِّ من الميّتِ والبعث؛ فاعتبر بها واعرف قدرةَ الله وفضله واشكره؛ فمن اعتبر شكر وأيقن، ومن غفل كفر؛ فاجعل الاعتبارَ بنعمةِ النارِ ومعرفةَ قدرةِ الله وشكرها دأبك."}},{"n":72,"reflection":{"text":"«أأنتم أنشأتم شجرتها أم نحن المنشئون» — أأنتم أنشأتم شجرةَ النارِ (التي تُقدَح منها) أم نحن المُنشِئون؟ ففي هذا إقرارٌ بأنّ إنشاءَها لله وحده؛ فأقرّ بأنّ إنشاءَ الشجرِ والنارِ فضلُ الله لا صنعك، فمن أنشأها يقدر على البعث، فأذعن واشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بأنّ الإنشاءَ لله، والشكرُ له، واليقينُ بقدرته."},"action":{"text":"تأمّل الإقرارَ بأنّ الإنشاءَ لله: أأنتم أنشأتم شجرتها — أي الشجرةَ التي تُقدَح منها النار (كالمرخِ والعفار) — أم نحن المُنشِئون لها؟ استفهامُ تقريرٍ وإلزام؛ فليس لهم في إنشائها شيء، بل هو فعلُ الله وحده «أأنتم أنشأتم شجرتها أم نحن المنشئون»؛ ففي هذا إقامةُ الحجّةِ بأنّ إنشاءَ شجرةِ النارِ ليس إليهم بل إلى الله وحده؛ فلا يقدرون على إنشاءِ شجرةٍ واحدة؛ فأقرّ أنت بأنّ إنشاءَ الشجرِ والنارِ فضلُ الله لا صنعك؛ الذي جعل لكم من الشجرِ الأخضرِ نارًا؛ أمّن خلق السماواتِ والأرضَ وأنزل لكم من السماءِ ماءً فأنبتنا به حدائقَ ذاتَ بهجة؛ فمن أنشأ الشجرَ وأودع فيه النارَ قادرٌ على بعثِ الخلق؛ فأذعن لله واشكر فضله وأيقن بقدرته على البعث؛ فمن أقرّ بذلك شكر وأيقن، ومن كابر كفر؛ فاجعل الإقرارَ بأنّ الإنشاءَ لله والشكرَ له واليقينَ بقدرته دأبك."}},{"n":73,"reflection":{"text":"«نحن جعلناها تذكرة ومتاعا للمقوين» — نحن جعلنا النارَ تذكرةً بنارِ جهنّم ومنفعةً للمسافرين وأهلِ الحاجة؛ ففي هذا بيانُ حكمةِ خلقِ النار؛ فاتّعظ بنارِ الدنيا فتذكّر نارَ الآخرة، فنارُ الدنيا تذكرةٌ بنارِ الآخرة، فاحذرها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بنارِ الدنيا وتذكّرُ نارِ الآخرة، وشكرُ منفعتها."},"action":{"text":"تأمّل حكمةَ خلقِ النار: نحن جعلنا النارَ تذكرةً — أي عظةً وتذكيرًا بنارِ جهنّم، فمن رآها تذكّر نارَ الآخرةِ فاتّقاها؛ ومتاعًا للمقوين — أي منفعةً ومصلحةً للمسافرين النازلين بالأرضِ القِواءِ (القفرِ الخالية)، أو لكلِّ من ينتفع بها من الناس «نحن جعلناها تذكرة ومتاعا للمقوين»؛ ففي هذا بيانُ حكمةِ خلقِ النار: عظةً تذكّر بنارِ الآخرة، ومنفعةً في الدنيا؛ فهي تذكرةٌ ومتاع؛ فاتّعظ أنت بنارِ الدنيا فتذكّر نارَ الآخرةِ فاتّقها؛ فأنذرتكم نارًا تلظّى؛ نارُكم هذه جزءٌ من سبعين جزءًا من نارِ جهنّم؛ فنارُ الدنيا أنموذجٌ يُذكِّر بنارِ الآخرة، وفيها منفعةٌ للعباد؛ فاتّعظ بها واحذر نارَ الآخرةِ واشكر منفعةَ نارِ الدنيا؛ فمن اتّعظ اتّقى، ومن غفل هلك؛ فاجعل الاتّعاظَ بنارِ الدنيا وتذكّرَ نارِ الآخرةِ وشكرَ منفعتها دأبك."}},{"n":74,"reflection":{"text":"«فسبح باسم ربك العظيم» — فنزّه ربَّك العظيمَ باسمه، وسبّحه شكرًا على نعمه وتنزيهًا له؛ ففي هذا أمرٌ بالتسبيحِ والتنزيه؛ فسبّح ربَّك العظيمَ وعظّمه، فالتسبيحُ حقُّ العظيمِ على عبده، فسبّح واشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تسبيحُ الله العظيمِ وتنزيهُه، وشكرُه على نعمه."},"action":{"text":"تأمّل الأمرَ بالتسبيح: فسبِّح — أيها الرسولُ ومن تبعك — باسمِ ربّك العظيمِ — أي نزّه الله العظيمَ عمّا لا يليق به، واذكر اسمه مُعظِّمًا مُنزِّهًا، شكرًا على ما أنعم به (من الزرعِ والماءِ والنار) وتنزيهًا له عن إنكارِ البعثِ الذي أقام عليه الأدلّة «فسبح باسم ربك العظيم»؛ ففي هذا أمرٌ بتسبيحِ الله العظيمِ وتنزيهه وتعظيمه، عقب الأدلّةِ على قدرته ونعمه؛ فحقُّ من هذه قدرتُه ونعمُه أن يُسبَّح ويُعظَّم؛ فسبّح أنت ربَّك العظيمَ ونزّهه وعظّمه؛ فسبّح بحمدِ ربّك وكن من الساجدين؛ سبّح اسمَ ربّك الأعلى؛ فاذكر اسمَه بالتسبيحِ والتنزيهِ والتعظيم؛ فالتسبيحُ حقُّ الربِّ العظيمِ على عبده، شكرًا وتنزيهًا؛ فسبّح واشكر وعظّم ربَّك؛ فمن سبّح ربَّه وعظّمه أفلح، ومن غفل خسر؛ فاجعل تسبيحَ الله العظيمِ وتنزيهَه وشكرَه على نعمه دأبك."}}]},{"title":"القسمُ بمواقعِ النجومِ وتعظيمُ القرآن","range":[75,82],"theme":"القسمُ بمواقعِ النجومِ وهو قسمٌ عظيم، على أنّ القرآنَ كريمٌ في كتابٍ مكنونٍ لا يمسّه إلا المطهّرون، تنزيلٌ من ربِّ العالمين؛ فكيف بهذا الحديثِ العظيمِ يتهاونون ويُكذّبون ويجعلون شكرَ رزقهم التكذيب؟","verses":[{"n":75,"reflection":{"text":"«فلا أقسم بمواقع النجوم» — أقسم الله بمواقعِ النجومِ (منازلها ومساقطها)؛ ففي هذا تعظيمُ شأنِ ما أقسم به تمهيدًا لتعظيمِ القرآن؛ فعظّم القرآنَ الذي أقسم الله على شرفه، فالقسمُ العظيمُ لأمرٍ عظيم، فأكرم القرآن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ الذي أقسم الله على شرفه، وإكرامُه."},"action":{"text":"تأمّل القسمَ العظيم: فلا أقسم — أي أُقسِم («لا» صلةٌ للتوكيد، أو ردٌّ لكلامٍ سابق) — بمواقعِ النجومِ — أي بمنازلها ومساقطها ومغاربها، أو بمواقعها حين تنكدر يومَ القيامة، أو بمواقعِ نجومِ القرآنِ حين نزوله «فلا أقسم بمواقع النجوم»؛ ففي هذا قسمٌ عظيمٌ من الله بمواقعِ النجوم، تمهيدًا لتعظيمِ القرآنِ المُقسَمِ على شرفه؛ فأقسم بهذه الآياتِ العظيمةِ في خلقه؛ فعظّم أنت القرآنَ الذي أقسم الله على شرفه؛ والنجمِ إذا هوى؛ والسماءِ ذاتِ البروج؛ فالله يُقسِم بمخلوقاتِه العظيمةِ تنبيهًا على عظمتها ودلالتها عليه؛ فالقسمُ العظيمُ إنما يكون لأمرٍ عظيمٍ هو القرآن؛ فأكرم القرآنَ وعظّمه وأقبل عليه؛ فمن عظّم القرآنَ أفلح، ومن استهان به خسر؛ فاجعل تعظيمَ القرآنِ الذي أقسم الله على شرفه وإكرامَه دأبك."}},{"n":76,"reflection":{"text":"«وإنه لقسم لو تعلمون عظيم» — وإنّ ذلك القسمَ بمواقعِ النجومِ قسمٌ عظيمٌ لو تعلمون عظمته؛ ففي هذا تعظيمُ شأنِ المُقسَمِ به والمُقسَمِ عليه؛ فأدرك عظمةَ ما أقسم الله به وعليه، فعظمةُ القسمِ تدلّ على عظمةِ المُقسَمِ عليه، فعظّم القرآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ عظمةِ القسمِ، وتعظيمُ القرآنِ المُقسَمِ عليه."},"action":{"text":"تأمّل عظمةَ القسم: وإنه — أي القسمَ بمواقعِ النجوم — لقسمٌ لو تعلمون — أيها الناسُ حقيقةَ عظمته — عظيمٌ؛ فهو قسمٌ عظيمٌ في نفسه، عظيمٌ فيما أقسم عليه، لكنّ الناسَ لا يُدرِكون كنه عظمته «وإنه لقسم لو تعلمون عظيم»؛ ففي هذا تعظيمُ شأنِ القسمِ بمواقعِ النجوم، وتنبيهٌ على أنّ عظمته تدلّ على عظمةِ المُقسَمِ عليه (القرآن)؛ فعظمةُ القسمِ بقدرِ عظمةِ المُقسَمِ عليه؛ فأدرك أنت عظمةَ ما أقسم الله به (النجومَ وآياتِ خلقه) وعليه (القرآنَ)؛ فلا أقسم بما تبصرون وما لا تبصرون إنه لقولُ رسولٍ كريم؛ فعظمةُ القسمِ تدلّك على عظمةِ القرآنِ وجلالِ قدره؛ فعظّم القرآنَ الذي هذا شأنُ القسمِ عليه؛ فمن أدرك عظمته عظّمه، ومن جهلها استهان به؛ فاجعل إدراكَ عظمةِ القسمِ وتعظيمَ القرآنِ المُقسَمِ عليه دأبك."}},{"n":77,"reflection":{"text":"«إنه لقرآن كريم» — إنّ هذا القرآنَ كريمٌ كثيرُ الخيرِ عظيمُ النفعِ جليلُ القدر؛ ففي هذا بيانُ شرفِ القرآنِ وكرمه؛ فأكرم القرآنَ الكريمَ وأقبل عليه بالتلاوةِ والتدبّرِ والعمل، فالقرآنُ كريمٌ يستحقّ الإكرام، فعظّمه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إكرامُ القرآنِ الكريمِ بالتلاوةِ والتدبّرِ والعمل."},"action":{"text":"تأمّل كرمَ القرآن: إنه — أي المُقسَمَ عليه — لقرآنٌ كريمٌ — أي كثيرُ الخيرِ والنفع، جليلُ القدر، عظيمُ الشأن، جامعٌ لكلِّ خيرٍ وعلمٍ وحكمة، كريمٌ على الله وعلى المؤمنين «إنه لقرآن كريم»؛ ففي هذا بيانُ شرفِ القرآنِ وكرمه وجلالةِ قدره؛ فهو كريمٌ في نفسه وفي نفعه وفي مصدره؛ فأكرم أنت القرآنَ الكريمَ بتلاوته وتدبّره والعملِ به وتعظيمه؛ ولقد آتيناك سبعًا من المثاني والقرآنَ العظيم؛ إنّ هذا القرآنَ يهدي للتي هي أقوم؛ في صحفٍ مكرّمةٍ مرفوعةٍ مطهّرة؛ فالقرآنُ كريمٌ يستحقّ غايةَ الإكرامِ والتعظيم؛ فأكرمه بحسنِ تلاوته وتدبّرِ معانيه والعملِ بأحكامه؛ فمن أكرمه أكرمه الله، ومن أهانه خسر؛ فاجعل إكرامَ القرآنِ الكريمِ بالتلاوةِ والتدبّرِ والعملِ دأبك."}},{"n":78,"reflection":{"text":"«في كتاب مكنون» — هذا القرآنُ مثبتٌ في كتابٍ مصونٍ (اللوحِ المحفوظِ)؛ ففي هذا بيانُ حفظِ القرآنِ وصونه؛ فعظّم قرآنًا هذا شأنُه في الحفظِ والصون، فالقرآنُ محفوظٌ مصون، فأكرمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ المحفوظِ المصون، وإكرامُه."},"action":{"text":"تأمّل صونَ القرآن: هذا القرآنُ الكريمُ في كتابٍ مكنونٍ — أي مصونٍ مستورٍ مكرّمٍ محفوظٍ عن التغييرِ والتبديلِ والباطل، وهو اللوحُ المحفوظُ، أو المصاحفُ التي بأيدي الملائكة «في كتاب مكنون»؛ ففي هذا بيانُ حفظِ القرآنِ وصونه وكرامةِ محلّه؛ فهو مثبتٌ في كتابٍ مصونٍ مكرّم؛ فعظّم أنت قرآنًا هذا شأنُه في الحفظِ والصونِ والكرامة؛ بل هو قرآنٌ مجيدٌ في لوحٍ محفوظ؛ في صحفٍ مكرّمةٍ مرفوعةٍ مطهّرة بأيدي سفرةٍ كرامٍ بررة؛ إنا نحن نزّلنا الذكرَ وإنا له لحافظون؛ فالقرآنُ محفوظٌ مصونٌ في أشرفِ محل؛ فأكرمه وعظّمه واحذر أن تُهينه؛ فمن عظّمه أفلح، ومن استهان به خسر؛ فاجعل تعظيمَ القرآنِ المحفوظِ المصونِ وإكرامَه دأبك."}},{"n":79,"reflection":{"text":"«لا يمسه إلا المطهرون» — لا يمسّ ذلك الكتابَ المكنونَ إلا الملائكةُ المطهّرون (أو لا يمسّ المصحفَ إلا المتطهّرون)؛ ففي هذا بيانُ طهارةِ القرآنِ ومحلّه؛ فطهّر نفسك لمسِّ المصحفِ وتلاوته، فالقرآنُ لا يمسّه إلا طاهر، فتطهّر له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التطهّرُ لمسِّ المصحفِ وتلاوته، وتعظيمُ القرآن."},"action":{"text":"تأمّل طهارةَ القرآنِ ومحلّه: لا يمسُّ الكتابَ المكنونَ (اللوحَ المحفوظَ) إلا المطهّرون — وهم الملائكةُ الكرامُ المطهّرون من الذنوب؛ أو لا يمسُّ المصحفَ إلا المتطهّرون من الحدثِ الأصغرِ والأكبرِ (على قراءةِ الخبرِ بمعنى النهي، أو حكمًا) «لا يمسه إلا المطهرون»؛ ففي هذا بيانُ طهارةِ القرآنِ وشرفِ محلّه، وأنه لا يمسّه إلا طاهر؛ فحُجِب عن غيرِ المطهّرين؛ فطهّر أنت نفسك بالوضوءِ لمسِّ المصحفِ، وطهّر قلبك من الشركِ والريبةِ لتدبّره؛ بأيدي سفرةٍ كرامٍ بررة؛ نزل به الروحُ الأمين؛ لا يأتيه الباطلُ من بين يديه ولا من خلفه؛ فالقرآنُ طاهرٌ مطهّرٌ لا يمسّه إلا طاهر؛ فتطهّر له ظاهرًا وباطنًا وعظّمه؛ فمن تطهّر له وعظّمه نال بركته، ومن استهان به حُرِم؛ فاجعل التطهّرَ لمسِّ المصحفِ وتلاوته وتعظيمَ القرآنِ دأبك."}},{"n":80,"reflection":{"text":"«تنزيل من رب العالمين» — هذا القرآنُ منزّلٌ من ربِّ العالمين؛ ففي هذا بيانُ مصدرِ القرآنِ الأعلى؛ فعظّم قرآنًا نزل من ربِّ العالمين، فالقرآنُ كلامُ ربِّ العالمين، فأكرمه واتّبعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ لأنه تنزيلٌ من ربِّ العالمين، واتّباعُه."},"action":{"text":"تأمّل مصدرَ القرآن: هذا القرآنُ الكريمُ تنزيلٌ — أي منزّلٌ — من ربِّ العالمين، خالقِ الخلقِ ومربّيهم ومدبّرِ أمرهم؛ فمصدره أعلى مصدرٍ وأشرفه «تنزيل من رب العالمين»؛ ففي هذا بيانُ مصدرِ القرآنِ الأعلى: أنه كلامُ ربِّ العالمين، نزل من عنده على رسوله؛ فليس من قولِ البشرِ ولا من قولِ الشياطين؛ فعظّم أنت قرآنًا نزل من ربِّ العالمين، فهو كلامه سبحانه؛ وإنه لتنزيلُ ربِّ العالمين نزل به الروحُ الأمين على قلبك؛ قل نزّله روحُ القدسِ من ربّك بالحقّ؛ لا يأتيه الباطل تنزيلٌ من حكيمٍ حميد؛ فالقرآنُ كلامُ ربِّ العالمين يستحقّ غايةَ التعظيمِ والاتّباع؛ فأكرمه واتّبعه واعمل به؛ فمن عظّمه واتّبعه اهتدى، ومن أعرض عنه ضلّ؛ فاجعل تعظيمَ القرآنِ لأنه تنزيلٌ من ربِّ العالمين واتّباعَه دأبك."}},{"n":81,"reflection":{"text":"«أفبهذا الحديث أنتم مدهنون» — أفبهذا القرآنِ العظيمِ أنتم متهاونون مكذّبون؟ ففي هذا إنكارٌ على من يتهاون بالقرآن؛ فاحذر التهاونَ بالقرآنِ وأقبل عليه بالتعظيم، فالتهاونُ بالقرآنِ خسران، فعظّمه وصدّق به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التهاونِ بالقرآن، والتصديقُ به وتعظيمُه."},"action":{"text":"تأمّل الإنكارَ على المتهاونين: أفبهذا الحديثِ — أي القرآنِ العظيمِ الكريم — أنتم مُدهِنون — أي متهاونون مكذّبون، مُداهنون فيه لا تُبالون به، أو تُكذّبون به وتُلينون القولَ فيه نفاقًا؟ استفهامُ إنكارٍ وتوبيخ «أفبهذا الحديث أنتم مدهنون»؛ ففي هذا إنكارٌ على من يتهاون بالقرآنِ العظيمِ ويُكذّب به أو يُداهن فيه؛ فكيف تتهاونون بكلامِ ربِّ العالمين؟ فاحذر أنت التهاونَ بالقرآنِ والتكذيبَ به والإعراضَ عنه؛ فبأيِّ حديثٍ بعده يؤمنون؛ أفتؤمنون ببعضِ الكتابِ وتكفرون ببعض؛ وإذا تُتلى عليهم آياتنا قالوا قد سمعنا؛ فالتهاونُ بالقرآنِ والتكذيبُ به خسرانٌ مبين؛ فأقبل عليه بالتعظيمِ والتصديقِ والعمل؛ فمن عظّمه وصدّق به أفلح، ومن تهاون به خسر؛ فاجعل الحذرَ من التهاونِ بالقرآنِ والتصديقَ به وتعظيمَه دأبك."}},{"n":82,"reflection":{"text":"«وتجعلون رزقكم أنكم تكذبون» — وتجعلون شكرَ رزقِكم (نعمةَ القرآنِ أو المطر) أنكم تكذّبون؟ ففي هذا توبيخٌ على مقابلةِ النعمةِ بالتكذيب؛ فاشكر نعمةَ الله بالتصديقِ لا بالتكذيب، فمقابلةُ النعمةِ بالتكذيبِ كفران، فاشكر وصدّق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الله بالتصديق، والحذرُ من مقابلتها بالتكذيب."},"action":{"text":"تأمّل توبيخَ المكذّبين: وتجعلون رزقكم — أي شكرَ رزقِكم وحظَّكم من نعمةِ الله (نعمةِ القرآن، أو نعمةِ المطرِ الذي يُنزِله الله) — أنكم تكذّبون؛ أي تجعلون موضعَ الشكرِ التكذيب، فتقابلون النعمةَ بالكفرانِ والتكذيب «وتجعلون رزقكم أنكم تكذبون»؛ ففي هذا توبيخٌ على مقابلةِ نعمةِ الله بالتكذيبِ بدل الشكر؛ فبدل أن تشكروا القرآنَ (أو المطرَ) تكذّبون؛ فاشكر أنت نعمةَ الله بالتصديقِ والطاعةِ لا بالتكذيبِ والكفران؛ ومن الناسِ من يقول آمنّا بالله؛ وتجعلون شكرَكم التكذيب (في قراءةٍ: رزقكم أي شكركم)؛ لئن شكرتم لأزيدنّكم ولئن كفرتم إنّ عذابي لشديد؛ فمقابلةُ النعمةِ بالتكذيبِ كفرانٌ يُوجِب زوالها والعقاب؛ فاشكر النعمَ بالتصديقِ والطاعةِ والعمل؛ فمن شكر زادت نعمته، ومن كذّب حُرِم؛ فاجعل شكرَ نعمةِ الله بالتصديقِ والحذرَ من مقابلتها بالتكذيبِ دأبك."}}]},{"title":"مشهدُ الاحتضارِ ومآلُ الأصنافِ الثلاثةِ وختامُ السورة","range":[83,96],"theme":"مشهدُ الاحتضارِ «فلولا إذا بلغت الحلقوم» وعجزُ الخلقِ وقربُ الله «ونحن أقرب إليه منكم»، ثم مآلُ كلِّ صنفٍ عند الموت: المقرّبون «فروح وريحان وجنت نعيم»، وأصحابُ اليمين «فسلام لك»، والمكذّبون الضالّون «فنزل من حميم وتصلية جحيم»، وختمُها «إن هذا لهو حق اليقين فسبح باسم ربك العظيم»","verses":[{"n":83,"reflection":{"text":"«فلولا إذا بلغت الحلقوم» — فهلّا إذا بلغت الروحُ الحلقومَ عند الموتِ رددتموها؟ ففي هذا تقريرُ العجزِ أمام الموت؛ فاعتبر بمشهدِ الاحتضارِ واستعدّ للموت، فالموتُ حقٌّ لا يُدفَع، فاستعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمشهدِ الاحتضار، والاستعدادُ للموت."},"action":{"text":"تأمّل مشهدَ الاحتضار: فلولا — أي فهلّا — إذا بلغت الروحُ الحلقومَ — أي وصلت النفسُ عند خروجها من الجسدِ إلى الحلقوم (مجرى الطعامِ والشراب)، وذلك عند سياقِ الموتِ وحضورِ الأجل «فلولا إذا بلغت الحلقوم»؛ ففي هذا تصويرُ مشهدِ الاحتضارِ العظيمِ وتقريرُ عجزِ الخلقِ عنده؛ فإذا بلغت الروحُ الحلقومَ فلا مردَّ لها؛ فاعتبر أنت بهذا المشهدِ الرهيبِ واستعدّ للموتِ قبل نزوله؛ كلّا إذا بلغت التراقي، وقيل من راقٍ، وظنّ أنه الفراق؛ حتى إذا جاء أحدهم الموتُ قال ربِّ ارجعون؛ ولو ترى إذ الظالمون في غمراتِ الموت؛ فالموتُ حقٌّ لا يُدفَع، وساعةُ الاحتضارِ ساعةُ عجزٍ وحسرةٍ لمن فرّط؛ فاستعدّ له بالإيمانِ والعملِ الصالحِ والتوبةِ قبل فواتِ الأوان؛ فمن استعدّ للموتِ نجا، ومن غفل عنه خسر؛ فاجعل الاعتبارَ بمشهدِ الاحتضارِ والاستعدادَ للموتِ دأبك."}},{"n":84,"reflection":{"text":"«وأنتم حينئذ تنظرون» — وأنتم حينئذٍ تنظرون إلى المحتضَرِ لا تملكون له شيئًا؛ ففي هذا بيانُ عجزِ الحاضرين عند الموت؛ فاعتبر بعجزِك عن ردِّ الموتِ عمّن تحبّ، فلا رادَّ للموت، فاستعدّ له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بالعجزِ عند الموت، والاستعدادُ لما بعده."},"action":{"text":"تأمّل عجزَ الحاضرين: وأنتم — أيها الحاضرون حول المحتضَر — حينئذٍ — أي حين بلوغِ روحه الحلقومَ — تنظرون إليه وهو يُعالِج سكراتِ الموتِ ولا تقدرون على دفعِ ذلك عنه ولا ردِّ روحه، بل تنظرون عاجزين «وأنتم حينئذ تنظرون»؛ ففي هذا بيانُ عجزِ الحاضرين عند الموتِ عن نفعِ المحتضَرِ أو ردِّ روحه؛ فتنظرون ولا تملكون شيئًا؛ فاعتبر أنت بعجزك عن ردِّ الموتِ عمّن تحبّ، فكيف بنفسك؟ ونحن أقربُ إليه منكم ولكن لا تبصرون؛ ولو ترى إذ الظالمون في غمراتِ الموتِ والملائكةُ باسطو أيديهم؛ فأنتم عاجزون عند الموتِ عن كلِّ شيء؛ فلا رادَّ للموتِ ولا دافعَ له؛ فاستعدّ لما بعد الموتِ بالإيمانِ والعملِ الصالح؛ فمن اعتبر بعجزه استعدّ، ومن غفل خسر؛ فاجعل الاعتبارَ بالعجزِ عند الموتِ والاستعدادَ لما بعده دأبك."}},{"n":85,"reflection":{"text":"«ونحن أقرب إليه منكم ولكن لا تبصرون» — ونحن أقربُ إلى المحتضَرِ منكم بعلمِنا وقدرتِنا وملائكتِنا، لكنكم لا تُبصِرون؛ ففي هذا بيانُ قربِ الله وإحاطته؛ فاستحضر قربَ الله منك وإحاطته بك، فالله أقربُ إليك من كلِّ أحد، فراقبه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ قربِ الله وإحاطته، ومراقبتُه في كلِّ حال."},"action":{"text":"تأمّل قربَ الله: ونحن أقربُ إليه — أي إلى المحتضَر — منكم بعلمِنا وقدرتِنا وإحاطتِنا، وبملائكتِنا الذين يقبضون روحه؛ ولكن لا تبصرون — أي لا تُدرِكون ذلك ولا ترون الملائكةَ ولا تعلمون كيفيّةَ قربِنا «ونحن أقرب إليه منكم ولكن لا تبصرون»؛ ففي هذا بيانُ قربِ الله من عبده بعلمه وقدرته وإحاطته، وأنه أقربُ إليه من كلِّ أحدٍ عند الموتِ وفي كلِّ حال؛ فقربُه سبحانه محيطٌ وإن لم يُبصَر؛ فاستحضر أنت قربَ الله منك وإحاطته بك؛ ونحن أقربُ إليه من حبلِ الوريد؛ وهو معكم أينما كنتم؛ ما يكون من نجوى ثلاثةٍ إلا هو رابعهم؛ فالله أقربُ إليك من كلِّ أحدٍ وإن لم تُبصِره؛ فراقبه في سرّك وعلانيتك واستحضر قربه؛ فمن استحضر قربَ الله راقبه، ومن غفل عنه ضلّ؛ فاجعل استحضارَ قربِ الله وإحاطته ومراقبتَه في كلِّ حالٍ دأبك."}},{"n":86,"reflection":{"text":"«فلولا إن كنتم غير مدينين» — فهلّا إن كنتم غيرَ مربوبين مجزيّين محاسبين؟ ففي هذا تحدٍّ لمنكري البعثِ والجزاء؛ فأيقن أنك مربوبٌ مدينٌ مجزيٌّ بعملك، فأنت مملوكٌ محاسب، فاستعدّ للجزاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنك مربوبٌ مجزيٌّ محاسب، والاستعدادُ للجزاء."},"action":{"text":"تأمّل التحدّي لمنكري الجزاء: فلولا — أي فهلّا — إن كنتم غيرَ مدينين — أي غيرَ مربوبين مملوكين، أو غيرَ مجزيّين محاسبين مبعوثين، كما تزعمون بإنكارِ البعث «فلولا إن كنتم غير مدينين»؛ ففي هذا تحدٍّ وإلزامٌ لمنكري البعثِ والجزاء: إن كنتم صادقين أنكم غيرُ مبعوثين ولا محاسبين، فردّوا الروحَ إذا بلغت الحلقوم؛ فعجزهم عن ردّها دليلٌ على أنهم مربوبون مقهورون مجزيّون؛ فأيقن أنت بأنك مربوبٌ مدينٌ مملوكٌ لله، مجزيٌّ بعملك، محاسبٌ على فعلك؛ مالكِ يومِ الدين؛ أفحسبتم أنما خلقناكم عبثًا وأنكم إلينا لا تُرجَعون؛ أيحسب الإنسانُ أن يُترَك سدى؛ فأنت مملوكٌ لله محاسبٌ مجزيٌّ لا محالة؛ فاستعدّ للجزاءِ والحسابِ بالإيمانِ والعملِ الصالح؛ فمن أيقن بأنه مجزيٌّ استعدّ، ومن أنكر ذلك خسر؛ فاجعل اليقينَ بأنك مربوبٌ مجزيٌّ محاسبٌ والاستعدادَ للجزاءِ دأبك."}},{"n":87,"reflection":{"text":"«ترجعونها إن كنتم صادقين» — فردّوا الروحَ إلى الجسدِ إن كنتم صادقين أنكم غيرُ محاسبين؟ ففي هذا إظهارُ عجزِهم وتكذيبُهم؛ فاعترف بعجزك وقدرةِ الله، فمن عجز عن ردِّ الروحِ فهو مقهور، فأذعن لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعترافُ بالعجزِ وقدرةِ الله، والإذعانُ له."},"action":{"text":"تأمّل إظهارَ عجزهم: ترجعونها — أي فردّوا الروحَ إلى الجسدِ بعد بلوغها الحلقوم — إن كنتم صادقين في زعمكم أنكم غيرُ مربوبين ولا مبعوثين ولا مقهورين «ترجعونها إن كنتم صادقين»؛ ففي هذا إظهارُ عجزِ منكري البعثِ وتكذيبُهم بأبلغِ حجّة؛ فإن كنتم صادقين أنه لا ربَّ يقهركم ولا بعثَ ولا جزاء، فردّوا الروحَ إذا بلغت الحلقوم؛ فعجزُكم عن ردّها دليلٌ قاطعٌ على أنكم مقهورون مربوبون؛ فاعترف أنت بعجزك المطلقِ وقدرةِ الله المطلقة؛ ما لهم من دونه من وليٍّ ولا واقٍ؛ فمن عجز عن ردِّ الروحِ لحظةَ خروجها فهو أعجزُ عن كلِّ شيء؛ فأذعن لله واعترف بربوبيّته وقدرته؛ فمن أذعن لله واعترف بعجزه آمن، ومن كابر هلك؛ فاجعل الاعترافَ بالعجزِ وقدرةِ الله والإذعانَ له دأبك."}},{"n":88,"reflection":{"text":"«فأما إن كان من المقربين» — فأمّا إن كان الميّتُ من المقرّبين السابقين؛ ففي هذا بيانُ مآلِ الصنفِ الأول عند الموت؛ فاعمل لتكون من المقرّبين فتنال بشراهم عند الموت، فبشرى المقرّبين عند الموتِ عظيمة، فاجتهد لتكون منهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكونَ من المقرّبين فتنال بشراهم عند الموت."},"action":{"text":"تأمّل مآلَ المقرّبين: فأمّا إن كان الميّتُ (المحتضَر) من المقرّبين — أي السابقين الذين تقدّم ذكرُ نعيمهم، أرفعِ أهلِ الجنّةِ منزلةً «فأما إن كان من المقربين»؛ ففي هذا بيانُ مآلِ الصنفِ الأولِ (المقرّبين) عند موتهم وما يُبشَّرون به؛ فهذا حالُ من كان من المقرّبين عند احتضاره؛ فاعمل أنت لتكون من المقرّبين السابقين فتنال بشراهم عند الموت؛ إنّ الذين قالوا ربّنا اللهُ ثم استقاموا تتنزّل عليهم الملائكةُ ألّا تخافوا ولا تحزنوا وأبشروا بالجنّة؛ يا أيتها النفسُ المطمئنّةُ ارجعي إلى ربّك راضيةً مرضية؛ فبشرى المقرّبين عند الموتِ عظيمةٌ بالروحِ والريحانِ والجنّة؛ فاجتهد بالسبقِ إلى الخيراتِ لتكون منهم؛ فمن كان منهم بُشِّر عند موته، ومن قصّر حُرِم؛ فاجعل العملَ لتكونَ من المقرّبين فتنال بشراهم عند الموتِ دأبك."}},{"n":89,"reflection":{"text":"«فروح وريحان وجنت نعيم» — فله راحةٌ ورزقٌ طيّبٌ (أو رحمةٌ) وجنّةُ نعيم؛ ففي هذا بيانُ بشرى المقرّبين عند الموت؛ فاطلب هذه البشرى بالسبقِ إلى الخيرات، فبشرى المقرّبين روحٌ وريحانٌ وجنّة، فاعمل لها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لبشرى المقرّبين: الروحِ والريحانِ وجنّةِ النعيم."},"action":{"text":"تأمّل بشرى المقرّبين: فإن كان من المقرّبين فله عند موته وفي آخرته روحٌ — أي راحةٌ واستراحةٌ من الدنيا وهمومها، أو رحمة؛ وريحانٌ — أي رزقٌ طيّبٌ حسنٌ، أو الرَّيحانُ المعروفُ يُستقبَل به؛ وجنّةُ نعيمٍ — أي بستانُ نعيمٍ دائمٍ يصير إليه «فروح وريحان وجنت نعيم»؛ ففي هذا بيانُ بشرى المقرّبين عند موتهم وفي مآلهم: الراحةُ والرزقُ الطيّبُ والجنّة؛ فيُبشَّرون بذلك عند الاحتضار؛ فاطلب أنت هذه البشرى بالسبقِ إلى الخيراتِ والإحسان؛ تتنزّل عليهم الملائكةُ ألّا تخافوا ولا تحزنوا وأبشروا بالجنّة؛ فادخلي في عبادي وادخلي جنّتي؛ فبشرى المقرّبين روحٌ وريحانٌ وجنّةُ نعيم؛ فاعمل لها بالسبقِ إلى الطاعاتِ والإخلاص؛ فمن كان من المقرّبين نالها، ومن قصّر حُرِمها؛ فاجعل العملَ لبشرى المقرّبين من الروحِ والريحانِ وجنّةِ النعيمِ دأبك."}},{"n":90,"reflection":{"text":"«وأما إن كان من أصحاب اليمين» — وأمّا إن كان الميّتُ من أصحابِ اليمين؛ ففي هذا بيانُ مآلِ الصنفِ الثاني عند الموت؛ فاعمل لتكون من أصحابِ اليمين فتنال سلامهم، فأصحابُ اليمين لهم سلامٌ عند الموت، فاجتهد لتكون منهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتكونَ من أصحابِ اليمين فتنال سلامهم."},"action":{"text":"تأمّل مآلَ أصحابِ اليمين: وأمّا إن كان الميّتُ (المحتضَر) من أصحابِ اليمين — وهم الصنفُ الثاني من أهلِ الجنّةِ دون المقرّبين «وأما إن كان من أصحاب اليمين»؛ ففي هذا بيانُ مآلِ الصنفِ الثاني (أصحابِ اليمين) عند موتهم وما يُبشَّرون به؛ فهذا حالُ من كان منهم عند احتضاره؛ فاعمل أنت لتكون من أصحابِ اليمينِ السعداء؛ فأصحابُ اليمينِ ما أصحابُ اليمين، في سدرٍ مخضود؛ الذين تتوفّاهم الملائكةُ طيّبين يقولون سلامٌ عليكم؛ فأصحابُ اليمينِ لهم عند الموتِ سلامٌ وطمأنينة؛ فاجتهد بالإيمانِ والعملِ الصالحِ لتكون منهم؛ فمن كان منهم نال سلامهم، ومن قصّر حُرِم؛ فاجعل العملَ لتكونَ من أصحابِ اليمينِ فتنال سلامهم دأبك."}},{"n":91,"reflection":{"text":"«فسلام لك من أصحاب اليمين» — فسلامٌ لك أيها المُخاطَبُ من إخوانك أصحابِ اليمين (أو سلامٌ لك أنك منهم)؛ ففي هذا بيانُ بشرى أصحابِ اليمين بالسلام؛ فاطلب هذا السلامَ بالإيمانِ والعمل، فسلامُ أصحابِ اليمين أمانٌ من العذاب، فاعمل له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ لتنال سلامَ أصحابِ اليمينِ وأمانهم."},"action":{"text":"تأمّل بشرى السلام: فسلامٌ لك — أي أمانٌ لك وسلامةٌ — من أصحابِ اليمين؛ أي يُقال له: سلامٌ لك، أنت من أصحابِ اليمينِ فلا خوفَ عليك؛ أو يُسلِّم عليه إخوانه أصحابُ اليمين؛ أو سلامٌ لك أنك ترى من نفسك أنك منهم «فسلام لك من أصحاب اليمين»؛ ففي هذا بيانُ بشرى أصحابِ اليمينِ بالسلامِ والأمانِ من العذاب؛ فيُبشَّرون بأنهم سالمون آمنون؛ فاطلب أنت هذا السلامَ والأمانَ بالإيمانِ والعملِ الصالح؛ ادخلوها بسلامٍ آمنين؛ سلامٌ قولًا من ربٍّ رحيم؛ وتتلقّاهم الملائكةُ هذا يومكم الذي كنتم توعدون؛ فسلامُ أصحابِ اليمينِ أمانٌ من العذابِ وبشرى بالنجاة؛ فاعمل له بالإيمانِ والطاعةِ والاستقامة؛ فمن كان منهم نال السلام، ومن قصّر حُرِم؛ فاجعل العملَ لتنال سلامَ أصحابِ اليمينِ وأمانهم دأبك."}},{"n":92,"reflection":{"text":"«وأما إن كان من المكذبين الضالين» — وأمّا إن كان الميّتُ من المكذّبين بالحقِّ الضالّين عن الهدى؛ ففي هذا بيانُ مآلِ الصنفِ الثالث عند الموت؛ فاحذر أن تكون من المكذّبين الضالّين، فمآلهم عند الموتِ سيّئ، فصدّق بالحقِّ واهتدِ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التكذيبِ والضلال، والتصديقُ بالحقِّ والاهتداء."},"action":{"text":"تأمّل مآلَ المكذّبين: وأمّا إن كان الميّتُ (المحتضَر) من المكذّبين — أي المكذّبين بالبعثِ والرسلِ والقرآن؛ الضالّين — أي التائهين عن طريقِ الحقِّ والهدى، أهلِ الشمال «وأما إن كان من المكذبين الضالين»؛ ففي هذا بيانُ مآلِ الصنفِ الثالث (المكذّبين الضالّين) عند موتهم وما يُستقبَلون به من العذاب؛ فهذا حالُ من كان منهم عند احتضاره؛ فاحذر أنت أن تكون من المكذّبين بالحقِّ الضالّين عن الهدى؛ الذين تتوفّاهم الملائكةُ ظالمي أنفسهم؛ ولو ترى إذ الظالمون في غمراتِ الموتِ والملائكةُ باسطو أيديهم أخرجوا أنفسكم؛ فمآلُ المكذّبين الضالّين عند الموتِ سيّئٌ من العذابِ والهوان؛ فصدّق أنت بالحقِّ واهتدِ إلى الصراطِ المستقيم؛ فمن صدّق واهتدى نجا، ومن كذّب وضلّ هلك؛ فاجعل الحذرَ من التكذيبِ والضلالِ والتصديقَ بالحقِّ والاهتداءَ دأبك."}},{"n":93,"reflection":{"text":"«فنزل من حميم» — فله ضيافةٌ من ماءٍ حارٍّ شديد؛ ففي هذا بيانُ مآلِ المكذّبين عند الموت؛ فاحذر أن يكون الحميمُ نزلك بالإيمانِ والتصديق، فنزلُ المكذّبين الحميم، فاجتنب أسبابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من نزلِ الحميم، واجتنابُ أسبابِ العذاب."},"action":{"text":"تأمّل نزلَ المكذّبين: فإن كان من المكذّبين الضالّين فنزلٌ — أي ضيافةٌ يُستقبَل بها عند موته وفي آخرته — من حميمٍ — أي ماءٍ حارٍّ متناهٍ في الحرارةِ يُسقاه ويُصبُّ عليه «فنزل من حميم»؛ ففي هذا بيانُ مآلِ المكذّبين الضالّين عند موتهم: نزلٌ من الحميم؛ فيُستقبَلون بالحميمِ بدل الروحِ والريحان؛ فاحذر أنت أن يكون الحميمُ نزلك بالإيمانِ والتصديقِ والاستقامة؛ هذا نزلهم يومَ الدين؛ يطوفون بينها وبين حميمٍ آن؛ وسُقوا ماءً حميمًا فقطّع أمعاءهم؛ فنزلُ المكذّبين الحميمُ في مقابلِ نزلِ المؤمنين الكريم؛ فاجتنب أسبابَ ذلك من التكذيبِ والضلالِ والمعاصي؛ فمن اجتنبها نجا، ومن ارتكبها هلك؛ فاجعل الحذرَ من نزلِ الحميمِ واجتنابَ أسبابِ العذابِ دأبك."}},{"n":94,"reflection":{"text":"«وتصلية جحيم» — وإدخالٌ في نارِ الجحيمِ يُقاسي حرَّها؛ ففي هذا بيانُ عذابِ المكذّبين؛ فاحذر نارَ الجحيمِ بالإيمانِ والعملِ الصالح، فمآلُ المكذّبين النار، فاجتنب أسبابها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من نارِ الجحيم، واجتنابُ أسبابها بالإيمانِ والعمل."},"action":{"text":"تأمّل عذابَ المكذّبين: وتصليةُ جحيمٍ — أي وإدخالٌ في نارِ الجحيمِ وإحراقٌ بها، يُصلاها ويُقاسي حرَّها وعذابها؛ فمع نزلِ الحميمِ تصليةُ الجحيم «وتصلية جحيم»؛ ففي هذا بيانُ تمامِ عذابِ المكذّبين الضالّين: نزلٌ من حميمٍ وتصليةُ جحيم؛ فيُصلَون النارَ ويُعذَّبون بها؛ فاحذر أنت نارَ الجحيمِ بالإيمانِ والعملِ الصالحِ والتوبة؛ ثم الجحيمَ صلّوه؛ ثم إنهم لصالو الجحيم؛ اصلوها فاصبروا أو لا تصبروا؛ فمآلُ المكذّبين الضالّين النارُ والعذابُ الأليم؛ فاجتنب أسبابها من التكذيبِ والضلالِ والكفرِ والمعاصي؛ فمن اجتنبها بالإيمانِ والعملِ نجا، ومن ارتكبها صار إليها؛ فاجعل الحذرَ من نارِ الجحيمِ واجتنابَ أسبابها بالإيمانِ والعملِ دأبك."}},{"n":95,"reflection":{"text":"«إن هذا لهو حق اليقين» — إنّ هذا الذي أُخبِرتَ به (من أحوالِ القيامةِ والأصنافِ الثلاثة) هو الحقُّ الثابتُ المُتيقَّن؛ ففي هذا تأكيدُ صدقِ ما سبق؛ فأيقن يقينًا جازمًا بحقّيّةِ ما أخبر الله به، فما أخبر الله به حقٌّ متيقَّن، فاعمل بمقتضاه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ الجازمُ بحقّيّةِ ما أخبر الله به، والعملُ بمقتضاه."},"action":{"text":"تأمّل تأكيدَ الحقّ: إنّ هذا — أي ما ذُكِر في هذه السورةِ من أحوالِ القيامةِ وانقسامِ الناسِ ثلاثةَ أصنافٍ ومآلِ كلٍّ منهم — لهو حقُّ اليقينِ — أي الحقُّ الثابتُ المُتيقَّنُ الذي لا شكَّ فيه ولا ريب، أعلى مراتبِ اليقين «إن هذا لهو حق اليقين»؛ ففي هذا تأكيدُ صدقِ ما تقدّم في السورةِ وأنه حقٌّ متيقَّنٌ لا مِريةَ فيه؛ فكلُّ ما ذُكِر حقٌّ ثابت؛ فأيقن أنت يقينًا جازمًا بحقّيّةِ ما أخبر الله به في كتابه؛ ثم لتُسألُنّ يومئذٍ عن النعيم؛ علمَ اليقين ثم عينَ اليقين، وإنه لحقُّ اليقين؛ وإنّ الدينَ لواقع؛ فما أخبر الله به حقٌّ متيقَّنٌ لا يعتريه شكٌّ ولا خلف؛ فأيقن به واعمل بمقتضاه من الاستعدادِ للقيامةِ والسبقِ إلى الخيرات؛ فمن أيقن به وعمل بمقتضاه نجا، ومن شكّ فيه أو غفل خسر؛ فاجعل اليقينَ الجازمَ بحقّيّةِ ما أخبر الله به والعملَ بمقتضاه دأبك."}},{"n":96,"reflection":{"text":"«فسبح باسم ربك العظيم» — فنزّه ربَّك العظيمَ باسمه، وسبّحه تعظيمًا وشكرًا؛ ففي هذا ختمُ السورةِ بالأمرِ بالتسبيح؛ فسبّح ربَّك العظيمَ وعظّمه، فالتسبيحُ حقُّ العظيمِ على عبده، فسبّح واعبده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تسبيحُ الله العظيمِ وتعظيمُه، وختمُ الأمورِ بذكره."},"action":{"text":"تأمّل ختمَ السورةِ بالتسبيح: فسبِّح — أيها الرسولُ ومن تبعك — باسمِ ربّك العظيمِ — أي نزّه الله العظيمَ عمّا لا يليق به، واذكر اسمه مُعظِّمًا مُنزِّهًا، تعظيمًا له وشكرًا على نعمه وتصديقًا بما أخبر «فسبح باسم ربك العظيم»؛ ففي هذا ختمُ السورةِ بالأمرِ بتسبيحِ الله العظيمِ وتنزيهه وتعظيمه، بعد تقريرِ القيامةِ والأصنافِ والأدلّةِ وأنّ ذلك حقُّ اليقين؛ فحقُّ من هذه عظمتُه أن يُسبَّح ويُعظَّم؛ فسبّح أنت ربَّك العظيمَ ونزّهه وعظّمه؛ فسبّح بحمدِ ربّك وكن من الساجدين؛ سبّح اسمَ ربّك الأعلى؛ فسبّح بحمدِ ربّك حين تقوم؛ فاذكر اسمَه بالتسبيحِ والتعظيم، واختم أمورك بذكره؛ فالتسبيحُ حقُّ الربِّ العظيمِ على عبده، تعظيمًا وشكرًا وعبادة؛ فسبّح واعبده وعظّمه؛ فمن سبّح ربَّه وعظّمه أفلح، ومن غفل خسر؛ فاجعل تسبيحَ الله العظيمِ وتعظيمَه وختمَ الأمورِ بذكره دأبك."}}]}],"coverage":{"covered":96,"total":96}};
